            // FIX (feature: "link the notification to the live streaming"): added
            // an optional 3rd param, onAction. When present the toast becomes
            // tappable (cursor:pointer + click handler) and auto-extends its
            // visible time slightly so it isn't a race to tap it before it
            // vanishes. Every existing 2-arg call site is unaffected.
            function showNotification(message, type = 'success', onAction = null) {
                window.showNotification = showNotification; // expose for inline handlers
                const el = document.getElementById('reward-notification');
                if (!el) return;
                // FIX (bug: "notifications not stable / appear duplicated"): this
                // reuses one shared toast element, but used to schedule an
                // independent hide-timer on every call without clearing the
                // previous one. A second notification arriving within 3.5s of
                // the first got cut short by the first call's stale timeout
                // (or the toast briefly flashed old text before updating),
                // which read as unstable/duplicated toasts. Dedupe identical
                // back-to-back messages and always reset the single timer.
                if (el._lastMessage === message && el.classList.contains('show')) {
                    if (el._hideTimer) clearTimeout(el._hideTimer);
                    el._hideTimer = setTimeout(() => el.classList.remove('show'), 3500);
                    return;
                }
                el._lastMessage = message;
                el.textContent = message;
                const colorMap = {
                    success: '#10B981',
                    error: '#EF4444',
                    warning: '#F59E0B',
                    info: '#1B2B8B',
                    live: '#DC2626'
                };
                el.style.backgroundColor = colorMap[type] || colorMap.success;
                el.style.color = '#ffffff';
                el.style.border = `2px solid rgba(255,255,255,0.3)`;
                el.classList.add('show');

                // Clean up any previous tap handler before attaching a new one —
                // otherwise a plain (non-actionable) toast that reuses this same
                // element right after an actionable one would still fire the
                // stale click handler.
                if (el._tkActionHandler) {
                    el.removeEventListener('click', el._tkActionHandler);
                    el._tkActionHandler = null;
                }
                if (typeof onAction === 'function') {
                    el.style.cursor = 'pointer';
                    el._tkActionHandler = function () {
                        onAction();
                        el.classList.remove('show');
                    };
                    el.addEventListener('click', el._tkActionHandler);
                } else {
                    el.style.cursor = 'default';
                }

                if (el._hideTimer) clearTimeout(el._hideTimer);
                const hideAfter = onAction ? 6000 : 3500; // give tappable toasts more time
                el._hideTimer = setTimeout(() => { el.classList.remove('show'); el._lastMessage = null; }, hideAfter);
            }

            // FIX (root cause of "no working notification system" / "link the
            // notification to the live streaming"): window.pushNotification was
            // CALLED in 30+ places across this codebase (gifts, likes, follows,
            // comments, new listings/reels, admin announcements, download
            // progress, and the "X is now LIVE" alert in app-live.js) but was
            // never actually DEFINED anywhere — every one of those call sites
            // was silently doing nothing behind a `typeof === 'function'` guard
            // that always evaluated false. This is the single missing piece
            // that reconnects all of them at once.
            //
            // Signature matches every existing call site in the codebase:
            //   pushNotification(message, type)
            //   pushNotification(message, type, icon, data)
            // `icon` isn't used yet (no notification-center UI exists to render
            // it into) but is accepted so callers that already pass it don't
            // need to change. `data.streamId` / `data.channelName` are what
            // make a 'live' notification actually DO something when tapped:
            // it joins that stream directly, instead of just being text.
            //
            // PATCH (bug: "notification bell / gift icon stopped working"):
            // app-notifications.js (loaded BEFORE this file) already defines
            // window.pushNotification with the real bell-badge/panel-list
            // implementation. This file used to reassign window.pushNotification
            // unconditionally, which — because this file loads AFTER
            // app-notifications.js — silently replaced that real
            // implementation with this toast-only fallback on every page
            // load. The button/bell still rendered, toasts still popped, but
            // the badge counter and panel list (owned by app-notifications.js)
            // never updated again, because the function that was supposed to
            // update them was gone. Same root cause broke the "sent you a
            // gift" notification, since it calls this same function. Now
            // this only defines the fallback if the real one isn't present
            // (e.g. app-notifications.js failed to load), so it can never
            // clobber the working implementation.
            if (typeof window.pushNotification !== 'function') {
            window.pushNotification = function (message, type, icon, data) {
                var onAction = null;
                if (type === 'live' && data && (data.streamId || data.channelName)) {
                    onAction = function () {
                        var sid = data.streamId || data.channelName;
                        var card = document.querySelector('.join-live-btn[data-stream-id="' + sid + '"]');
                        if (card) {
                            card.click();
                        } else if (typeof window.joinLiveAsViewer === 'function') {
                            window.joinLiveAsViewer(data.channelName || sid, data.hostName || '');
                        }
                    };
                }
                showNotification(message, (type === 'live') ? 'live' : (type || 'info'), onAction);
            };
            }

            // Global upload progress bar helper
            function showUploadProgress(containerId, pct) {
                let cont = document.getElementById(containerId + '-progress');
                if (!cont) {
                    const parentEl = document.getElementById(containerId);
                    if (!parentEl) return;
                    cont = document.createElement('div');
                    cont.id = containerId + '-progress';
                    cont.className = 'upload-progress-container';
                    cont.innerHTML = '<div class="upload-progress-bar" style="width:0%;"></div>';
                    parentEl.appendChild(cont);
                }
                const bar = cont.querySelector('.upload-progress-bar');
                if (bar) { bar.style.width = pct + '%'; }
                if (pct >= 100) setTimeout(() => { if(cont) cont.remove(); }, 800);
            }

