            function generateCaptcha() {
                const captchaCodeEl = document.getElementById('captcha-code');
                if (!captchaCodeEl) return;
                const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
                captchaCode = Array.from({ length: 6 }, () => chars.charAt(Math.floor(Math.random() * chars.length))).join('');
                captchaCodeEl.textContent = captchaCode;
                const loginCaptchaInput = document.getElementById('login-captcha-input');
                if(loginCaptchaInput) loginCaptchaInput.value = '';
            }

            function formatWhatsAppText(text) {
    // SURGICAL FIX: also highlight @mentions and #hashtags
    if (typeof text !== 'string') return '';
    // Apply standard formatting first, then highlight tags
                if (!text) return '';
                // Escape HTML first
                let t = text.replace(/</g, '&lt;').replace(/>/g, '&gt;');
                // Auto-linkify URLs (YouTube, WhatsApp, social, https, www,
                // AND a bare domain typed with no http/www prefix at all —
                // e.g. "joinempyrean.com" or "wa.me/234..." typed plain).
                // FIX ("wasn't sensitive to .com"): the previous regex only
                // matched a URL that already started with "https?://" or
                // "www." — a bare "something.com" with neither prefix never
                // matched anything, so it rendered as plain, unclickable
                // text. The third alternative below matches a dotted
                // domain-looking token ending in a real TLD even with no
                // prefix at all, then the callback adds "https://" onto it
                // the same way the www. case already does. A negative
                // lookbehind keeps this from firing on the domain half of
                // an email address (name@example.com) since that's a
                // different, not-yet-requested feature (mailto: links).
                t = t.replace(/(https?:\/\/[^\s<>"'&]+|www\.[^\s<>"'&]+\.[a-z]{2,}[^\s<>"'&]*|(?<![a-zA-Z0-9@._-])(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+(?:com|net|org|edu|gov|mil|co|io|ng|app|dev|me|info|biz|xyz|live|tv|ai|shop|store|online|site|uk|ca|us|in|za|gh|ke)(?:\/[^\s<>"'&]*)?\b)/gi, function(rawUrl) {
                    // Strip trailing sentence punctuation ("Visit joinempyrean.com." — the
                    // final "." ends the SENTENCE, not the URL) so it isn't swallowed into the link.
                    var trail = '';
                    var trailMatch = rawUrl.match(/[.,!?;:)\]]+$/);
                    if (trailMatch) { trail = trailMatch[0]; rawUrl = rawUrl.slice(0, -trail.length); }
                    if (!rawUrl) return rawUrl + trail;
                    const url = rawUrl;
                    const href = /^https?:\/\//i.test(url) ? url : 'https://' + url;
                    let icon = '<i class="fas fa-link"></i>';
                    if (href.includes('youtube.com') || href.includes('youtu.be')) icon = '<i class="fab fa-youtube"></i>';
                    else if (href.includes('whatsapp.com') || href.includes('wa.me')) icon = '<i class="fab fa-whatsapp"></i>';
                    else if (href.includes('twitter.com') || href.includes('x.com')) icon = '<i class="fab fa-twitter"></i>';
                    else if (href.includes('instagram.com')) icon = '<i class="fab fa-instagram"></i>';
                    else if (href.includes('linkedin.com')) icon = '<i class="fab fa-linkedin"></i>';
                    else if (href.includes('facebook.com') || href.includes('fb.com')) icon = '<i class="fab fa-facebook"></i>';
                    const label = url.length > 45 ? url.substring(0,45) + '…' : url;
                    return '<a href="' + href + '" target="_blank" rel="noopener noreferrer" style="color:var(--secondary);text-decoration:underline;font-weight:500;">' + icon + ' ' + label + '</a>' + trail;
                });
                // WhatsApp-style formatting
                t = t
                    .replace(/\*(.*?)\*/g, '<strong>$1</strong>')
                    .replace(/_(.*?)_/g, '<em>$1</em>')
                    .replace(/~(.*?)~/g, '<s>$1</s>')
                    .replace(/`(.*?)`/g, '<code style="background:rgba(10,14,39,0.08);padding:1px 5px;border-radius:4px;font-family:monospace;font-size:0.88em;">$1</code>')
                    .replace(/\n/g, '<br>');
                // @mention highlighting -- clickable, navigates to user profile
                t = t.replace(/@([a-zA-Z0-9_\.]+)/g, function(match, username) {
                    return '<a href="#" class="mention-tag" data-username="' + username + '" '
                        + 'style="color:var(--secondary);font-weight:700;text-decoration:none;'
                        + 'background:rgba(27,43,139,0.09);border-radius:4px;padding:1px 4px;">'
                        + '@' + username + '</a>';
                });
                // #hashtag highlighting
                t = t.replace(/#([a-zA-Z0-9_]+)/g, function(match, tag) {
                    return '<a href="#" class="hashtag-tag" data-tag="' + tag + '" '
                        + 'style="color:var(--accent-color);font-weight:700;text-decoration:none;'
                        + 'background:rgba(245,197,24,0.12);border-radius:4px;padding:1px 4px;">'
                        + '#' + tag + '</a>';
                });
                return t;
            }

            // ── @MENTION & #HASHTAG AUTOCOMPLETE SYSTEM ─────────────────────────
            // Attaches to any textarea/contenteditable with class 'mention-aware'
            // or explicitly to the quick-post-text and post-form-text inputs.
            // ── GLOBAL BLANK-SCREEN RECOVERY (error + unhandledrejection) ──
            (function _blankScreenGuard() {
                // FIX (root cause of "chevron panel / accept button / viewer
                // count all worked once, then stopped" — confirmed by the
                // pattern in every debug session: the tools work fine until
                // the FIRST console error appears, then nothing responds
                // right afterward): #go-live-modal-overlay is a
                // `.modal-overlay-container`, not a `.content-section` — so
                // while a live stream is open, `anyVisible` below can
                // evaluate to FALSE (no `.content-section` is on screen,
                // just the full-screen live overlay sitting on top of
                // everything). Any error firing during a live session used
                // to trip this guard 1200ms later and force `#dashboard`'s
                // display back to 'block' underneath the still-open live
                // overlay — and the errors that do this most often are
                // totally harmless (Agora WebRTC ICE-negotiation hiccups on
                // a weak connection show up as generic cross-origin "Script
                // error." events, which still count here). The forced
                // dashboard reflow is what actually broke the host control
                // panel, accept button, and viewer-count taps right after
                // the first error — not the error itself. Skipping recovery
                // entirely while the live overlay is open fixes this: a
                // live stream is never "the blank screen" this guard exists
                // to catch.
                function _liveOverlayOpen() {
                    var ov = document.getElementById('go-live-modal-overlay');
                    return !!(ov && ov.classList.contains('show'));
                }
                function _checkAndRecover() {
                    try {
                        if (_liveOverlayOpen()) return;
                        var sections = document.querySelectorAll('.content-section');
                        // FIX (2026-08-27 — "click a section, everything spills/
                        // overlaps"): this used to check s.style.display, the raw
                        // INLINE style property, which is an empty string ('') for
                        // every section whose visibility comes from the
                        // .content-section/.active CSS classes (the normal case,
                        // set by navigateTo() — it never touches .style.display).
                        // That made anyVisible go false for a perfectly normal,
                        // correctly-showing section, so ANY unrelated uncaught
                        // error anywhere in the app (a third-party ad script, an
                        // Agora hiccup, etc. — routine in this app) would fire this
                        // 1200ms later and hit the recovery branch below.
                        // getComputedStyle reads what the browser actually
                        // rendered (post-CSS), so it agrees with offsetParent and
                        // no longer misfires on a section that's genuinely showing.
                        var anyVisible = Array.from(sections).some(function(s) {
                            return window.getComputedStyle(s).display !== 'none' && s.offsetParent !== null;
                        });
                        if (!anyVisible) {
                            // FIX (2026-08-27): this used to set dash.style.display
                            // = 'block' directly — a raw INLINE style that beats
                            // the stylesheet's `.content-section { display: none; }`
                            // (that base rule has no !important in style.css or
                            // nav-patch.css) for the REST OF THE PAGE SESSION,
                            // regardless of whatever section the person navigates
                            // to next. navigateTo() only ever toggles the .active
                            // CLASS, so it could never undo this — #dashboard's
                            // content (News & Updates, Reels, Community Feed) was
                            // left permanently bleeding through underneath every
                            // section visited afterward. Routing recovery through
                            // navigateTo() instead uses the same .active-class
                            // mechanism every normal navigation already uses, so it
                            // can be superseded by the very next real navigation
                            // exactly like any other section change.
                            if (typeof window.navigateTo === 'function') {
                                window.navigateTo('dashboard');
                                console.warn('[Empyrean] Blank screen recovered → dashboard');
                            } else {
                                var dash = document.getElementById('dashboard');
                                if (dash) { dash.classList.add('active'); console.warn('[Empyrean] Blank screen recovered → dashboard (navigateTo unavailable, used .active fallback)'); }
                            }
                        }
                    } catch(_) {}
                }
                window.addEventListener('error', function() { setTimeout(_checkAndRecover, 1200); }, true);
                window.addEventListener('unhandledrejection', function() { setTimeout(_checkAndRecover, 1200); });
                // Periodic safety net: check every 5s for first 60s
                var _safetyCount = 0;
                var _safetyInt = setInterval(function() {
                    if (++_safetyCount > 12) { clearInterval(_safetyInt); return; }
                    if (_liveOverlayOpen()) return;
                    if (document.body && document.body.children.length > 2) _checkAndRecover();
                }, 5000);
            })();

            // ── INJECT READ-MORE / ARTICLE COLLAPSE CSS ─────────────
            (function _injectArticleCollapseCSS() {
                if (document.getElementById('_article_collapse_css')) return;
                var s = document.createElement('style');
                s.id = '_article_collapse_css';
                s.textContent = [
                    '.story-content { position: relative; }',
                    '.news-item-content { position: relative; }',
                    /* Legacy classes kept in case any not-yet-refreshed cached
                       card still carries the old two-link markup. */
                    '.post-text-rest { display: none; }',
                    '.post-read-more, .post-read-less {',
                    '  display: inline-block; margin-top: 6px;',
                    '  font-size: 0.83rem; font-weight: 700;',
                    '  color: var(--secondary, #1B2B8B);',
                    '  cursor: pointer; text-decoration: none;',
                    '  border: none; background: none; padding: 0;',
                    '  transition: opacity 0.15s;',
                    '}',
                    '.post-read-more:hover, .post-read-less:hover { opacity: 0.7; }',
                    '.post-text-overflow { color: inherit; display: inline; }',
                    /* Note: the actual 10-line clip is applied as an inline
                       max-height (computed per-post from its own real,
                       measured line-height) rather than a CSS class -- a
                       "-webkit-line-clamp" rule here was tried first, but on
                       real devices it never actually clipped anything
                       (scrollHeight came back identical to clientHeight
                       regardless of post length), so the JS engine now sets
                       max-height directly and there's nothing to do in CSS
                       for the clip itself. */
                    /* Unified chevron expand/collapse toggle -- single button,
                       used across feed posts, news items, and saved posts.
                       FIX: on Android WebView, "border:none; background:none"
                       alone doesn't always remove the native <button> chrome
                       (shows as a boxed/framed border around the label) --
                       -webkit-appearance/appearance must be reset too, plus
                       outline:none so no focus ring appears either. Colour
                       simplified to a single flat blue for the label+chevron. */
                    '.post-expand-toggle {',
                    '  -webkit-appearance: none; appearance: none;',
                    '  display: inline-flex; align-items: center; gap: 4px;',
                    '  margin-top: 6px; border: none; outline: none; background: transparent;',
                    '  padding: 0; box-shadow: none; border-radius: 0;',
                    '  font-size: 0.83rem; font-weight: 700;',
                    '  color: #1877F2; cursor: pointer;',
                    '  transition: opacity 0.15s;',
                    '}',
                    '.post-expand-toggle:hover, .post-expand-toggle:focus, .post-expand-toggle:active {',
                    '  border: none; outline: none; background: transparent; box-shadow: none;',
                    '}',
                    '.post-expand-toggle:hover { opacity: 0.7; }',
                    '.post-expand-chevron { transition: transform 0.2s ease; flex-shrink: 0; stroke: #1877F2; }',
                    '.story-content.expanded .post-expand-chevron,',
                    '.news-item-content.expanded .post-expand-chevron { transform: rotate(180deg); }',
                    /* Suggested-for-you card -- profile-header style */
                    '.suggested-user-card {',
                    '  background: white;',
                    '  border-radius: 14px;',
                    '  overflow: hidden;',
                    '  border: 1.5px solid rgba(10,14,39,0.08);',
                    '  box-shadow: 0 2px 12px rgba(10,14,39,0.07);',
                    '  display: flex;',
                    '  flex-direction: column;',
                    '  cursor: pointer;',
                    '  transition: box-shadow 0.18s, transform 0.18s;',
                    '  min-width: 240px;',
                    '  max-width: 280px;',
                    '  flex-shrink: 0;',
                    '}',
                    '.suggested-user-card:hover { box-shadow: 0 6px 24px rgba(27,43,139,0.14); transform: translateY(-2px); }',
                ].join('\n');
                document.head.appendChild(s);
            })();

            (function _initMentionSystem() {
                // Build/refresh user list from Firestore 'users' collection
                window._mentionUserList = window._mentionUserList || [];
                if (typeof fbDb !== 'undefined') {
                    fbDb.collection('users').orderBy('username').limit(200).get()
                        .then(function(snap) {
                            window._mentionUserList = snap.docs.map(function(d) {
                                return { username: d.data().username || '', fullName: d.data().fullName || '', avatar: d.data().avatar || '' };
                            }).filter(function(u) { return u.username; });
                        }).catch(function() {});
                }

                function _getDropdown() {
                    var el = document.getElementById('_mention_dropdown');
                    if (!el) {
                        el = document.createElement('div');
                        el.id = '_mention_dropdown';
                        el.style.cssText = [
                            'position:fixed','z-index:99999','background:white',
                            'border:1.5px solid rgba(27,43,139,0.18)','border-radius:12px',
                            'box-shadow:0 8px 32px rgba(10,14,39,0.18)','max-height:220px',
                            'overflow-y:auto','display:none','min-width:200px','padding:6px 0'
                        ].join(';');
                        document.body.appendChild(el);
                    }
                    return el;
                }

                function _hideDropdown() {
                    var d = document.getElementById('_mention_dropdown');
                    if (d) d.style.display = 'none';
                    window._mentionActiveInput = null;
                    window._mentionTriggerChar = null;
                }

                function _showSuggestions(input, query, triggerChar, rect) {
                    var dropdown = _getDropdown();
                    var list = triggerChar === '@' ? window._mentionUserList : [];
                    var filtered = [];
                    if (triggerChar === '@') {
                        filtered = list.filter(function(u) {
                            return u.username.toLowerCase().startsWith(query.toLowerCase()) ||
                                   u.fullName.toLowerCase().includes(query.toLowerCase());
                        }).slice(0, 8);
                    }
                    if (!filtered.length) { _hideDropdown(); return; }

                    dropdown.innerHTML = filtered.map(function(u) {
                        return '<div class="_mention_item" data-username="' + u.username + '" style="'
                            + 'display:flex;align-items:center;gap:10px;padding:8px 14px;cursor:pointer;'
                            + 'border-radius:8px;transition:background 0.15s;"'
                            + ' onmouseover="this.style.background=\'rgba(27,43,139,0.07)\'"'
                            + ' onmouseout="this.style.background=\'\'">'
                            + '<img src="' + (u.avatar || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(u.username) + '&background=1B2B8B&color=fff&size=40') + '"'
                            + ' style="width:32px;height:32px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.src=\'https://ui-avatars.com/api/?name=U&background=1B2B8B&color=fff&size=40\'">'
                            + '<div><div style="font-weight:700;font-size:0.88rem;color:var(--primary);">@' + u.username + '</div>'
                            + '<div style="font-size:0.76rem;color:#888;">' + u.fullName + '</div></div></div>';
                    }).join('');

                    // Position dropdown at computed location
                    dropdown.style.left = rect.left + 'px';
                    dropdown.style.top = rect.bottom + 'px';
                    dropdown.style.display = 'block';
                    window._mentionActiveInput = input;
                    window._mentionTriggerChar = triggerChar;
                    window._mentionQuery = query;

                    // Click handler for each item
                    dropdown.querySelectorAll('._mention_item').forEach(function(item) {
                        item.addEventListener('mousedown', function(e) {
                            e.preventDefault();
                            var chosen = item.dataset.username;
                            var val = input.value;
                            var pos = input.selectionStart;
                            // Find where the @query starts
                            var before = val.substring(0, pos);
                            var trigIdx = before.lastIndexOf(triggerChar);
                            var newVal = val.substring(0, trigIdx) + triggerChar + chosen + ' ' + val.substring(pos);
                            input.value = newVal;
                            input.selectionStart = input.selectionEnd = trigIdx + chosen.length + 2;
                            input.focus();
                            _hideDropdown();
                            // Dispatch input event so any listeners update
                            input.dispatchEvent(new Event('input', { bubbles: true }));
                        });
                    });
                }

                function _onInput(e) {
                    var input = e.target;
                    if (!input || input.tagName !== 'TEXTAREA') return;
                    var val = input.value;
                    var pos = input.selectionStart;
                    var before = val.substring(0, pos);
                    // Detect @word being typed -- allow at start or after any whitespace/newline
                    var atMatch = before.match(/(?:^|[\s\n])@([a-zA-Z0-9_\.]*)$/);
                    if (atMatch) {
                        var query = atMatch[1];
                        // Position dropdown just below the textarea
                        var coords = input.getBoundingClientRect();
                        var dropLeft = Math.min(coords.left + 16, window.innerWidth - 220);
                        var dropBottom = coords.bottom + 4;
                        // If there isn't room below, put it above
                        if (dropBottom + 220 > window.innerHeight) {
                            dropBottom = Math.max(coords.top - 224, 4);
                        }
                        _showSuggestions(input, query, '@', { left: dropLeft, bottom: dropBottom });
                    } else {
                        _hideDropdown();
                    }
                }

                function _onKeyDown(e) {
                    var dropdown = document.getElementById('_mention_dropdown');
                    if (!dropdown || dropdown.style.display === 'none') return;
                    if (e.key === 'Escape') { _hideDropdown(); }
                    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
                        e.preventDefault();
                        var items = Array.from(dropdown.querySelectorAll('._mention_item'));
                        var cur = items.findIndex(function(i) { return i.classList.contains('_active'); });
                        items.forEach(function(i) { i.classList.remove('_active'); i.style.background = ''; });
                        var next = e.key === 'ArrowDown' ? cur + 1 : cur - 1;
                        next = Math.max(0, Math.min(next, items.length - 1));
                        if (items[next]) { items[next].classList.add('_active'); items[next].style.background = 'rgba(27,43,139,0.07)'; }
                    }
                    if (e.key === 'Enter' || e.key === 'Tab') {
                        var activeItem = dropdown.querySelector('._mention_item._active') || dropdown.querySelector('._mention_item');
                        if (activeItem && window._mentionActiveInput) {
                            activeItem.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
                            e.preventDefault();
                        }
                    }
                }

                // Attach to document -- works for all textareas including dynamically added ones
                document.addEventListener('input', _onInput, true);
                document.addEventListener('keydown', _onKeyDown, true);
                document.addEventListener('click', function(e) {
                    if (!e.target.closest('#_mention_dropdown') && !e.target.matches('textarea')) {
                        _hideDropdown();
                    }
                }, true);

                // ── CHEVRON EXPAND / COLLAPSE for long posts ──────────
                // Single unified toggle button (post-expand-toggle) shared by
                // every post type that renders long text (feed posts, news
                // items, saved posts) -- state lives entirely on the
                // "expanded" class of the wrapping .story-content /
                // .news-item-content, so CSS handles the visual toggle and
                // this handler just flips the one class + button label.
                // Legacy .post-read-more/.post-read-less two-link markup
                // (from any not-yet-refreshed cached card) is still honoured
                // as a fallback so older rendered cards don't break.
                document.addEventListener('click', function(e) {
                    var toggle = e.target.closest('.post-expand-toggle');
                    if (toggle) {
                        e.preventDefault();
                        e.stopPropagation();
                        e.stopImmediatePropagation();
                        var sc = toggle.closest('.story-content, .news-item-content');
                        if (!sc) return;
                        var pEl = sc.querySelector('.post-text-wrap') || sc.querySelector('p') || sc;
                        var isExpanded = sc.classList.toggle('expanded');
                        if (isExpanded) {
                            pEl.style.maxHeight = 'none';
                            pEl.style.overflow = 'visible';
                        } else {
                            var savedHeight = pEl.dataset.threeLineHeight;
                            pEl.style.maxHeight = savedHeight ? (savedHeight + 'px') : 'none';
                            pEl.style.overflow = savedHeight ? 'hidden' : 'visible';
                        }
                        toggle.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
                        var label = toggle.querySelector('.post-expand-label');
                        if (label) label.textContent = isExpanded ? 'Show less' : 'Show more';
                        return;
                    }
                    var rmLink = e.target.closest('.post-read-more');
                    if (rmLink) {
                        e.preventDefault();
                        e.stopPropagation();
                        var sc3 = rmLink.closest('.story-content, .news-item-content');
                        if (!sc3) return;
                        var overflow = sc3.querySelector('.post-text-overflow');
                        var rest = sc3.querySelector('.post-text-rest');
                        if (overflow) overflow.style.display = 'none';
                        if (rest) rest.style.display = 'inline';
                        rmLink.style.display = 'none';
                        var rl = sc3.querySelector('.post-read-less');
                        if (rl) rl.style.display = 'inline-block';
                        return;
                    }
                    var rlLink = e.target.closest('.post-read-less');
                    if (rlLink) {
                        e.preventDefault();
                        e.stopPropagation();
                        var sc2 = rlLink.closest('.story-content, .news-item-content');
                        if (!sc2) return;
                        var overflow2 = sc2.querySelector('.post-text-overflow');
                        var rest2 = sc2.querySelector('.post-text-rest');
                        if (overflow2) overflow2.style.display = 'inline';
                        if (rest2) rest2.style.display = 'none';
                        rlLink.style.display = 'none';
                        var rm2 = sc2.querySelector('.post-read-more');
                        if (rm2) rm2.style.display = 'inline-block';
                        return;
                    }
                }, true);

                // ── UNIVERSAL LINE-CLAMP TRUNCATION ("after 3 lines, every post") ──
                // FIX (report — "make the article in the general public
                // dashboard field expansion start from after the first 3
                // lines across sections"): this one engine already applies
                // to every .story-content (feed posts) AND .news-item-content
                // (news articles) alike — "across sections" — so lowering
                // its one shared threshold covers both at once. Was 10
                // lines; now 3, per that request.
                // Single, generic engine that applies to EVERY post automatically --
                // it doesn't matter which function rendered the card, only that it
                // contains a .story-content or .news-item-content wrapper (feed
                // posts, news items, saved posts, and any future post type that
                // reuses those same wrapper classes all get this for free).
                //
                // How it works: rather than guessing "how many lines will this
                // text take up" from a character count (fragile -- depends on
                // font size, container width, emoji, mentions, wrapping), we
                // apply a CSS 10-line clamp to the actual rendered paragraph and
                // then MEASURE it (scrollHeight vs clientHeight) once the browser
                // has laid it out. Only if it genuinely overflows 3 lines do we
                // add the chevron toggle button; short posts are left alone.
                function _empInitLineClamp(container) {
                    if (!container || container._lcInit) return;

                    // FIX (report — "collapse and expand button has refused
                    // to work... particular to that post"): everything from
                    // here down runs once per post and never retries if it
                    // throws — container._lcInit / p._lcClamped are set
                    // FIRST, before any of the actual measurement/DOM work,
                    // so if something about ONE specific post's rendered
                    // content (e.g. an unusual embed with no wrapping <p>,
                    // see the youtube-embed note a few lines down) throws an
                    // exception partway through, that post is left
                    // permanently marked "already handled" with no toggle
                    // and no way to ever retry — while every other post,
                    // whose content doesn't hit that edge case, keeps
                    // working normally. That matches "other posts are fine,
                    // just this one" far better than a systemic bug would.
                    // Wrapping the whole body in try/catch means a bad post
                    // logs a clear, findable warning (open devtools, look
                    // for "[EmpLineClamp] failed for") instead of silently
                    // leaving that one post's Show more non-functional with
                    // no trace of why.
                    try {
                        _empInitLineClampInner(container);
                    } catch (eLc) {
                        var _lcPid = (container.closest('[data-post-id]') && container.closest('[data-post-id]').dataset.postId) || '(no post id)';
                        console.warn('[EmpLineClamp] failed for post', _lcPid, '-- Show more may not work for this post:', eLc);
                    }
                }

                function _empInitLineClampInner(container) {
                    // FIX (report — "admin announcement chevron visible at
                    // times, fails in most cases"): an announcement's
                    // .story-content is replaced with buildAnnouncementFeedHTML's
                    // markup (.admin-announcement-block > .ann-body-wrap >
                    // p.ann-body), which has its OWN dedicated 3-line clamp +
                    // chevron system (_wireAnnouncementBodyToggle, further
                    // below in this file). Without this check, the fallback
                    // a few lines down (`container.querySelector('p')`)
                    // reaches straight past that structure and finds the
                    // exact same p.ann-body — so THIS engine also clamped it
                    // and appended a second, different toggle button
                    // (.post-expand-toggle) alongside the announcement's own
                    // (.ann-toggle-btn). Both run their own rAF-retry
                    // measurement loop against the identical element and
                    // whichever one resolves last silently overwrites the
                    // other's maxHeight — a genuine race, which is exactly
                    // why it looked "random" (worked sometimes, broken
                    // most times) rather than reliably broken or working.
                    // Announcement cards are excluded here and handled
                    // exclusively by their own system from now on.
                    if (container.querySelector('.ann-body-wrap')) { container._lcInit = true; return; }
                    container._lcInit = true;

                    // COMPLETE: some card types (SOS requests, crisis reports)
                    // render MORE THAN ONE <p> inside .story-content/.news-item-content
                    // -- e.g. description + "amount needed" line, or description +
                    // location. Previously only the first <p> was ever measured/
                    // clamped, so the second line permanently leaked out below the
                    // clamp, uncounted toward the 3 lines, and never got hidden
                    // behind "Show more". Fix: if there's more than one direct <p>,
                    // wrap them all in one measurable element so the WHOLE post's
                    // text -- not just its first paragraph -- is what gets clamped
                    // and what the toggle expands/collapses. Single-<p> posts (the
                    // common case) are untouched, same element as before.
                    var directParas = container.querySelectorAll(':scope > p');
                    var p;
                    if (directParas.length > 1) {
                        p = document.createElement('div');
                        p.className = 'post-text-wrap';
                        directParas[0].parentNode.insertBefore(p, directParas[0]);
                        directParas.forEach(function (para) { p.appendChild(para); });
                    } else {
                        // FIX (report — same "particular to that post" chevron
                        // bug): a post whose text contains ONLY a recognized
                        // YouTube link renders via handleYoutubeEmbed(), whose
                        // markup is an embed block with no wrapping <p> at all
                        // (see createNewPostElement's own youtubeFound branch,
                        // which skips rendering mediaHTML in that case). With
                        // no direct <p> AND no <p> anywhere in the container,
                        // this used to fall all the way back to `container`
                        // itself — clamping/measuring the WHOLE .story-content,
                        // embed included, as if it were the text paragraph.
                        // The toggle button (appended to that same container)
                        // ended up a child of the very element being
                        // maxHeight/overflow-clamped, which could leave it
                        // visually clipped or otherwise non-functional for
                        // that one post while every plain-text post (which
                        // always has a real <p>) was unaffected. Skip
                        // clamping entirely when there's no real text
                        // paragraph to measure -- an embed with no caption
                        // text doesn't need a "Show more" toggle anyway.
                        var _directP = directParas[0] || container.querySelector('p');
                        if (!_directP) return;
                        p = _directP;
                    }
                    if (p._lcClamped) return;
                    p._lcClamped = true;

                    var _attempts = 0;
                    function _measure() {
                        _attempts++;
                        // A hidden container (e.g. this post landed in the DOM
                        // while its section/tab wasn't the active one, or during
                        // an animation) reports clientHeight 0/scrollHeight 0 --
                        // keep retrying (cheap: just a rAF) until it's actually
                        // visible, instead of deciding based on a zero-height
                        // snapshot.
                        var notYetVisible = p.clientHeight === 0 && p.scrollHeight === 0;
                        if (notYetVisible && _attempts < 60) {
                            requestAnimationFrame(_measure);
                            return;
                        }

                        // FIX (bug: chevron never appearing on ANY post): the
                        // previous version applied a "-webkit-line-clamp: 10"
                        // CSS class and then compared scrollHeight to
                        // clientHeight -- but real devices showed those two
                        // ALWAYS equal (e.g. 713/713, 1521/1521) regardless of
                        // post length, meaning the clamp CSS was never actually
                        // taking effect (cascade/support issue), so nothing
                        // ever registered as overflowing. This version doesn't
                        // depend on -webkit-line-clamp at all: it reads the
                        // paragraph's OWN real line-height, computes what 10
                        // lines is in pixels for this exact element/font/width,
                        // and compares that directly against its natural full
                        // (unclamped) scrollHeight -- plain arithmetic, nothing
                        // that depends on a CSS feature's cascade or browser
                        // support.
                        var cs = window.getComputedStyle(p);
                        var lineHeight = parseFloat(cs.lineHeight);
                        if (!lineHeight || isNaN(lineHeight)) {
                            var fontSize = parseFloat(cs.fontSize) || 15;
                            lineHeight = fontSize * 1.4; // "normal" line-height fallback
                        }
                        var threeLinesHeight = Math.round(lineHeight * 3);
                        var fullHeight = p.scrollHeight;
                        var overflowing = fullHeight > threeLinesHeight + 2;

                        if (window._empLineClampDebug) {
                            console.log('[EmpLineClamp] measured', container.closest('[data-post-id]') && container.closest('[data-post-id]').dataset.postId,
                                'attempts:', _attempts, 'lineHeight:', lineHeight, 'threeLinesHeight:', threeLinesHeight,
                                'fullHeight:', fullHeight, 'overflowing:', overflowing);
                        }

                        if (overflowing) {
                            p.dataset.threeLineHeight = String(threeLinesHeight);
                            p.style.maxHeight = threeLinesHeight + 'px';
                            p.style.overflow = 'hidden';
                            if (!container.querySelector('.post-expand-toggle')) {
                                var btn = document.createElement('button');
                                btn.type = 'button';
                                btn.className = 'post-expand-toggle';
                                btn.setAttribute('aria-expanded', 'false');
                                btn.innerHTML =
                                    '<span class="post-expand-label">Show more</span>' +
                                    '<svg class="post-expand-chevron" viewBox="0 0 24 24" width="14" height="14" fill="none" ' +
                                    'stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">' +
                                    '<polyline points="6 9 12 15 18 9"></polyline></svg>';
                                // BULLETPROOF: set the no-border/blue look directly as
                                // inline styles, not just via the .post-expand-toggle
                                // CSS class. Inline styles always win regardless of any
                                // other stylesheet's specificity, load order, or a
                                // stale cached copy of the separate injected <style>
                                // block -- so as long as THIS exact JS is what's
                                // running, the button is guaranteed borderless every
                                // time, with no dependency on the CSS cascade at all.
                                btn.style.cssText =
                                    '-webkit-appearance:none;appearance:none;' +
                                    'display:inline-flex;align-items:center;gap:4px;' +
                                    'margin-top:6px;border:none;outline:none;background:transparent;' +
                                    'padding:0;box-shadow:none;border-radius:0;' +
                                    'font-size:0.83rem;font-weight:700;color:#1877F2;cursor:pointer;';
                                container.appendChild(btn);
                            }
                        }
                        // If not overflowing, leave the paragraph completely
                        // untouched -- no clamp, no button needed.
                    }

                    // Two rAFs so we measure after the browser has actually
                    // painted the paragraph (fonts/images can shift layout a
                    // frame late, especially right after innerHTML injection).
                    requestAnimationFrame(function () {
                        requestAnimationFrame(_measure);
                    });
                }

                // Re-measure everything whenever the app switches sections/tabs
                // -- posts that were rendered while hidden (clientHeight 0 at
                // first attempt) get a fresh, reliable measurement once their
                // section actually becomes visible.
                document.addEventListener('empyrean-section-change', function () {
                    setTimeout(function () {
                        document.querySelectorAll('.story-content, .news-item-content').forEach(function (c) {
                            if (!c.querySelector('.post-expand-toggle')) {
                                // Force a fresh measurement pass for this one --
                                // covers both "was hidden, never got a real
                                // measurement" and "genuinely doesn't need one".
                                var p = c.querySelector('.post-text-wrap') || c.querySelector('p') || c;
                                c._lcInit = false;
                                if (p) p._lcClamped = false;
                                _empInitLineClamp(c);
                            }
                        });
                    }, 200);
                });

                // FIX (report — "the collapse and expand button has
                // refused to work for this... card"): _measure() reads
                // the paragraph's REAL rendered line-height/scrollHeight
                // the very first time _empInitLineClamp runs on it --
                // often within a frame or two of the card landing in the
                // DOM, which can be before the page's web fonts (Syne/
                // Fraunces/Inter, loaded via @import/<link> — see
                // style.css) have actually finished downloading. Text
                // measured in the browser's fallback font can come out a
                // different height than the same text once the real font
                // swaps in, so the 3-lines-vs-overflowing decision this
                // makes can be permanently wrong: either a "Show more"
                // toggle gets added to a paragraph that was never really
                // overflowing (tapping it toggles the button's own label/
                // aria-expanded state, but there was no extra hidden text
                // to reveal, so nothing visibly happens -- exactly the
                // "button refused to work" symptom), or a genuinely
                // long paragraph gets measured as short and never gets a
                // toggle at all. Once _lcClamped is set true after that
                // first pass, nothing re-checks it unless the section
                // changes (the handler just above) -- so a bad
                // font-loading-race measurement can stick around
                // indefinitely on whatever section the post first
                // rendered in. document.fonts.ready resolves once every
                // requested font has actually finished loading, so this
                // forces exactly one corrective re-measurement pass, the
                // same reset-and-remeasure the section-change handler
                // above already uses, right after that happens.
                if (window.document && document.fonts && document.fonts.ready && typeof document.fonts.ready.then === 'function') {
                    document.fonts.ready.then(function () {
                        document.querySelectorAll('.story-content, .news-item-content').forEach(function (c) {
                            var p = c.querySelector('.post-text-wrap') || c.querySelector('p') || c;
                            c._lcInit = false;
                            if (p) {
                                p._lcClamped = false;
                                // Undo whatever the pre-font-load pass decided so
                                // _measure() starts from a clean slate -- otherwise
                                // a wrongly-added toggle/maxHeight from the bad
                                // measurement would persist even after re-running.
                                p.style.maxHeight = '';
                                p.style.overflow = '';
                                delete p.dataset.threeLineHeight;
                            }
                            var oldToggle = c.querySelector('.post-expand-toggle');
                            if (oldToggle) oldToggle.remove();
                            c.classList.remove('expanded');
                            _empInitLineClamp(c);
                        });
                    }).catch(function () {});
                }

                function _empScanForLineClamp(root) {
                    if (!root) return;
                    if (root.nodeType === 1) {
                        if (root.matches && root.matches('.story-content, .news-item-content')) {
                            _empInitLineClamp(root);
                        }
                        if (root.querySelectorAll) {
                            root.querySelectorAll('.story-content, .news-item-content').forEach(_empInitLineClamp);
                        }
                    }
                }

                var _lineClampObserver = new MutationObserver(function (mutations) {
                    mutations.forEach(function (m) {
                        m.addedNodes.forEach(_empScanForLineClamp);
                    });
                });
                _lineClampObserver.observe(document.body, { childList: true, subtree: true });
                // Catch anything already rendered before this observer attached
                document.querySelectorAll('.story-content, .news-item-content').forEach(_empInitLineClamp);

                // Manual diagnostic -- call window._empRescanLineClamp() directly
                // in the console at any time (no reload needed, so a runtime
                // debug flag can never get wiped out by a page refresh). Forces
                // every current post to re-measure right now and prints exactly
                // what it finds for each one.
                window._empRescanLineClamp = function () {
                    var nodes = document.querySelectorAll('.story-content, .news-item-content');
                    console.log('[EmpLineClamp] Rescanning ' + nodes.length + ' post(s)...');
                    nodes.forEach(function (c) {
                        var p = c.querySelector('.post-text-wrap') || c.querySelector('p') || c;
                        var pid = (c.closest('[data-post-id]') && c.closest('[data-post-id]').dataset.postId) || '(no post id)';
                        c._lcInit = false;
                        if (p) p._lcClamped = false;
                        window._empLineClampDebug = true;
                        _empInitLineClamp(c);
                        console.log('[EmpLineClamp] queued re-measure for', pid, '-- text length:', (p.textContent || '').length);
                    });
                };

                // Verification marker -- open devtools console and look for this
                // line to confirm the engine is actually running.
                console.log('[EmpLineClamp] ✅ Engine active [build 20260711d -- borderless blue toggle] -- watching for .story-content/.news-item-content. Run window._empRescanLineClamp() any time for a live per-post report (no reload needed).');

                // ── Read-more truncation for news items ──
                // REMOVED: this used to be its own 280-character-cut observer,
                // duplicating logic that now lives once, generically, in the
                // universal line-clamp truncation system further below (which
                // watches for ANY .story-content/.news-item-content and
                // measures actual rendered lines rather than guessing from a
                // character count). News items are .news-item-content, so
                // they're already covered by that one system -- nothing
                // news-specific needs to happen here anymore.

                // ── MULTI-MEDIA SWIPE COUNTER ──────────────────────────────
                // Adjustment (2026-08-15): posts with 2+ media items render
                // via .story-media-container[data-count]/[data-layout] --
                // markup shared by every post-media renderer in the app
                // (app-feed.js, app-profile.js, app-sos.js, app-thread.js,
                // etc.), the same "one shared component, one shared fix"
                // pattern the line-clamp engine above already relies on.
                // style.css now makes any container with data-count > 1
                // scroll horizontally with native scroll-snap (no JS needed
                // for the swipe motion itself) -- this just adds the small
                // "current/total" counter badge and keeps it in sync with
                // which item is currently scrolled into view. Solo posts
                // (data-count="1") are skipped entirely, same as style.css's
                // own :not([data-count="1"]) guard.
                function _empInitMediaSwipeCounter(container) {
                    if (!container || container._empSwipeInit) return;
                    var count = parseInt(container.getAttribute('data-count') || '0', 10);
                    if (!count || count < 2) return;
                    container._empSwipeInit = true;

                    var items = container.querySelectorAll('.story-media-item');
                    var badge = document.createElement('div');
                    badge.className = 'story-media-counter';
                    badge.textContent = '1/' + count;
                    container.appendChild(badge);

                    function _update() {
                        if (!container.clientWidth) return;
                        var idx = Math.round(container.scrollLeft / container.clientWidth);
                        idx = Math.max(0, Math.min(items.length - 1, idx));
                        badge.textContent = (idx + 1) + '/' + count;
                    }
                    container.addEventListener('scroll', function () {
                        // rAF-throttled -- scroll fires far more often than the
                        // badge actually needs to repaint.
                        if (container._empSwipeRaf) return;
                        container._empSwipeRaf = requestAnimationFrame(function () {
                            container._empSwipeRaf = null;
                            _update();
                        });
                    }, { passive: true });
                }

                function _empScanForMediaSwipe(root) {
                    if (!root) return;
                    if (root.nodeType !== 1) return;
                    if (root.matches && root.matches('.story-media-container[data-count]')) {
                        _empInitMediaSwipeCounter(root);
                    }
                    if (root.querySelectorAll) {
                        root.querySelectorAll('.story-media-container[data-count]').forEach(_empInitMediaSwipeCounter);
                    }
                }

                var _mediaSwipeObserver = new MutationObserver(function (mutations) {
                    mutations.forEach(function (m) {
                        m.addedNodes.forEach(_empScanForMediaSwipe);
                    });
                });
                _mediaSwipeObserver.observe(document.body, { childList: true, subtree: true });
                // Catch anything already rendered before this observer attached.
                document.querySelectorAll('.story-media-container[data-count]').forEach(_empInitMediaSwipeCounter);

                console.log('[EmpMediaSwipe] ✅ Posts with 2+ media items now swipe horizontally (scroll-snap) with a "current/total" counter badge; solo posts unchanged.');

                // Handle click on @mention tags -- show real mini profile popup
                document.addEventListener('click', function(e) {
                    var mentionLink = e.target.closest('.mention-tag');
                    if (mentionLink) {
                        e.preventDefault();
                        var uname = mentionLink.dataset.username;
                        if (!uname) return;
                        // Remove any existing mention popup
                        var old = document.getElementById('_mention_profile_popup');
                        if (old) old.remove();
                        // Look up user from mentionUserList or mockUsers
                        var _u = null;
                        if (window._mentionUserList) {
                            _u = window._mentionUserList.find(function(u) { return u.username === uname; });
                        }
                        if (!_u && window.mockUsers) {
                            var _mu = Object.values(window.mockUsers).find(function(u) { return u.username === uname; });
                            if (_mu) _u = _mu;
                        }
                        var popup = document.createElement('div');
                        popup.id = '_mention_profile_popup';
                        popup.style.cssText = 'position:fixed;z-index:99999;background:white;border-radius:16px;box-shadow:0 8px 32px rgba(10,14,39,0.2);padding:16px;min-width:240px;max-width:280px;border:1.5px solid rgba(10,14,39,0.08);';
                        var _av = (_u && (_u.avatar || _u.profilePhoto)) || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(uname) + '&background=1B2B8B&color=fff&size=60');
                        var _fn = (_u && (_u.fullName || _u.name)) || uname;
                        var _bio = (_u && _u.bio) || '';
                        var _followers = (_u && _u.followersCount) || 0;
                        popup.innerHTML = '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">'
                            + '<img src="' + _av + '" style="width:48px;height:48px;border-radius:50%;object-fit:cover;flex-shrink:0;border:2px solid var(--secondary);" onerror="this.src=this.dataset.fb" data-fb="https://ui-avatars.com/api/?name=U&background=1B2B8B&color=fff&size=60">'
                            + '<div><div style="font-weight:700;font-size:0.92rem;color:var(--primary);">' + _fn + '</div>'
                            + '<div style="font-size:0.78rem;color:#888;">@' + uname + '</div></div></div>'
                            + (_bio ? '<div style="font-size:0.82rem;color:#555;margin-bottom:8px;">' + _bio + '</div>' : '')
                            + '<div style="font-size:0.78rem;color:#888;margin-bottom:10px;">' + _followers + ' followers</div>'
                            + '<div style="display:flex;gap:8px;">'
                            + '<button class="_mention_view_profile" data-uname="' + uname + '" style="flex:1;padding:8px;background:var(--primary);color:white;border:none;border-radius:8px;font-size:0.82rem;font-weight:700;cursor:pointer;">View Profile</button>'
                            + '<button class="_mention_popup_close" style="padding:8px 12px;background:rgba(10,14,39,0.07);color:var(--primary);border:none;border-radius:8px;font-size:0.82rem;font-weight:700;cursor:pointer;"><i class="fas fa-times"></i></button>'
                            + '</div>';
                        // Position near click
                        var rect = mentionLink.getBoundingClientRect();
                        var top = rect.bottom + 8;
                        var left = Math.min(rect.left, window.innerWidth - 300);
                        if (top + 180 > window.innerHeight) top = rect.top - 190;
                        popup.style.top = top + 'px';
                        popup.style.left = left + 'px';
                        document.body.appendChild(popup);
                        popup.querySelector('._mention_popup_close').addEventListener('click', function() { popup.remove(); });
                        popup.querySelector('._mention_view_profile').addEventListener('click', function() {
                            popup.remove();
                            // Find user id from mockUsers
                            var _uid = null;
                            if (window.mockUsers) {
                                var found = Object.entries(window.mockUsers).find(function(kv) { return kv[1].username === uname; });
                                if (found) _uid = found[0];
                            }
                            if (_uid && typeof renderUserProfile === 'function') {
                                renderUserProfile(_uid);
                                if (typeof navigateTo === 'function') navigateTo('profile');
                            } else {
                                if (typeof navigateTo === 'function') navigateTo('profile');
                                if (typeof showNotification === 'function') showNotification('@' + uname + ' profile', 'info');
                            }
                        });
                        // Close on outside click
                        setTimeout(function() {
                            document.addEventListener('click', function _closePopup(ev) {
                                if (!popup.contains(ev.target)) { popup.remove(); document.removeEventListener('click', _closePopup); }
                            });
                        }, 100);
                        return;
                    }
                    // Handle click on #hashtag tags -- boost trending + filter feed
                    var hashLink = e.target.closest('.hashtag-tag');
                    if (hashLink) {
                        e.preventDefault();
                        var tag = hashLink.dataset.tag;
                        if (!tag) return;
                        // Boost this tag's trending score on every click
                        if (typeof window._incrementTag === 'function') window._incrementTag(tag);
                        // Remove existing hashtag popup
                        var oldHp = document.getElementById('_hashtag_popup');
                        if (oldHp) oldHp.remove();
                        // Gather matching posts from feed
                        var _matchPosts = [];
                        document.querySelectorAll('.impact-story, .news-list-item').forEach(function(el) {
                            var txt = (el.querySelector('.story-content, .news-item-content')?.textContent || '').toLowerCase();
                            if (txt.includes('#' + tag.toLowerCase())) _matchPosts.push(el);
                        });
                        var hp = document.createElement('div');
                        hp.id = '_hashtag_popup';
                        hp.style.cssText = 'position:fixed;z-index:99999;background:white;border-radius:16px;box-shadow:0 8px 32px rgba(10,14,39,0.2);padding:16px;min-width:240px;max-width:300px;border:1.5px solid rgba(10,14,39,0.08);max-height:320px;overflow-y:auto;';
                        var rect2 = hashLink.getBoundingClientRect();
                        var top2 = rect2.bottom + 8;
                        var left2 = Math.min(rect2.left, window.innerWidth - 320);
                        if (top2 + 200 > window.innerHeight) top2 = rect2.top - 210;
                        hp.style.top = top2 + 'px';
                        hp.style.left = left2 + 'px';
                        hp.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">'
                            + '<strong style="font-size:0.95rem;color:var(--primary);">#' + tag + '</strong>'
                            + '<button id="_ht_close" style="background:none;border:none;font-size:1.1rem;cursor:pointer;color:#888;">✕</button></div>'
                            + '<div style="font-size:0.82rem;color:#888;margin-bottom:10px;">' + _matchPosts.length + ' post' + (_matchPosts.length !== 1 ? 's' : '') + ' with this tag</div>'
                            + '<button id="_ht_filter" style="width:100%;padding:9px;background:var(--accent-color);color:var(--primary);border:none;border-radius:8px;font-size:0.84rem;font-weight:700;cursor:pointer;margin-bottom:4px;">'
                            + '<i class="fas fa-filter"></i> Filter feed by #' + tag + '</button>';
                        document.body.appendChild(hp);
                        document.getElementById('_ht_close').addEventListener('click', function() { hp.remove(); });
                        document.getElementById('_ht_filter').addEventListener('click', function() {
                            hp.remove();
                            // Highlight/scroll to first matching post
                            if (_matchPosts.length > 0) {
                                _matchPosts.forEach(function(p, i) {
                                    p.style.outline = i === 0 ? '2px solid var(--accent-color)' : '';
                                    p.style.borderRadius = '12px';
                                });
                                _matchPosts[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
                                setTimeout(function() { _matchPosts.forEach(function(p) { p.style.outline = ''; }); }, 3000);
                                if (typeof showNotification === 'function') showNotification('Showing ' + _matchPosts.length + ' post(s) tagged #' + tag, 'info');
                            } else {
                                if (typeof showNotification === 'function') showNotification('No posts found with #' + tag, 'info');
                            }
                        });
                        setTimeout(function() {
                            document.addEventListener('click', function _closeHp(ev) {
                                if (!hp.contains(ev.target)) { hp.remove(); document.removeEventListener('click', _closeHp); }
                            });
                        }, 100);
                    }
                });


                console.log('[Mentions] @mention & #hashtag system initialised');
            })();

            // ═══════════════════════════════════════════════════════════
            // TAG ENGINE: @mention notifications + #hashtag trending
            // DISABLED (2026-08-30): superseded by app-tags.js, which loads
            // BEFORE this file (see index.html's <script> order) and already
            // defines window._trendingTags / window._incrementTag /
            // window._processPostTags / window._renderTrendingWidget — the
            // exact same globals this block redefines. Left running, this
            // duplicate silently overwrote all of those with its own older
            // copy every time this file loaded, including its own separate
            // 'trending_tags' onSnapshot listener (a second, redundant
            // listener alongside app-tags.js's) and its own
            // _injectTrendingWidget(), which still injected the Trending
            // card straight onto the general #dashboard/right-sidebar via
            // the old fallback chain — exactly the "general public home
            // page" placement the 2026-08-30 request asked to move OFF of
            // and into a dedicated #trending nav section instead. app-tags.js
            // now owns that section (see its own _injectTrendingWidget/
            // _renderTagsWidget), so this whole legacy copy is retired
            // in place (kept, not deleted, per this codebase's own
            // no-deletion convention) rather than fixed a second time in
            // two places. window._processPostTags / _incrementTag calls
            // elsewhere in this file are unaffected — app-tags.js's own
            // versions of those globals are what's actually invoked, since
            // this block no longer overwrites them.
            (function _initTagEngine() {
                if (window._empyreanTagsLoaded) return; // app-tags.js already owns this feature
                // ── In-memory trending store (backed by Firestore when available) ──
                window._trendingTags = window._trendingTags || {};

                // Load existing trending from Firestore once
                function _loadTrending() {
                    if (typeof fbDb === 'undefined' || !fbDb) return;
                    fbDb.collection('trending_tags').orderBy('score', 'desc').limit(20)
                        .get().then(function(snap) {
                            snap.forEach(function(doc) {
                                window._trendingTags[doc.id] = doc.data().score || 0;
                            });
                            _renderTrendingWidget();
                        }).catch(function(){});
                }
                setTimeout(_loadTrending, 1200);

                // ── Increment trend score for a hashtag ──
                function _incrementTag(tag) {
                    if (!tag) return;
                    var t = tag.toLowerCase().replace(/[^a-z0-9_]/g, '');
                    if (!t) return;
                    window._trendingTags[t] = (window._trendingTags[t] || 0) + 1;
                    // Persist to Firestore
                    try {
                        if (typeof fbDb !== 'undefined' && fbDb) {
                            fbDb.collection('trending_tags').doc(t).set({
                                tag: t, score: window._trendingTags[t], lastUsed: new Date().toISOString()
                            }, { merge: true }).catch(function(){});
                        }
                    } catch(e) {}
                    _renderTrendingWidget();
                }
                /* FIX (tech debt / silent-collision risk, 2026-07-18):
                   app-tags.js already defines window._incrementTag as a
                   dedicated, documented module, and loads BEFORE this file.
                   This block is a byte-for-byte functional duplicate that
                   was unconditionally overwriting it — currently harmless
                   since both write the same shape, but it's exactly the
                   same load-order collision pattern that broke the
                   marketplace chat overlay (one file's edits silently
                   stopped mattering because a near-identical copy elsewhere
                   loaded later and won). Guarding so app-tags.js's copy
                   stays authoritative and future edits only need to happen
                   in one place. */
                if (typeof window._incrementTag !== 'function') window._incrementTag = _incrementTag;

                // ── Send in-app notification to a mentioned user ──
                function _notifyMentionedUser(mentionedUsername, postText, posterName, postId) {
                    if (typeof fbDb === 'undefined' || !fbDb) return;
                    // Find user doc by username
                    fbDb.collection('users').where('username', '==', mentionedUsername).limit(1)
                        .get().then(function(snap) {
                            if (snap.empty) return;
                            var targetDoc = snap.docs[0];
                            var notifRef = fbDb.collection('notifications').doc();
                            notifRef.set({
                                id: notifRef.id,
                                type: 'mention',
                                toUserId: targetDoc.id,
                                fromUserId: (typeof userState !== 'undefined' && userState) ? userState.id : 'unknown',
                                fromName: posterName || 'Someone',
                                message: (posterName || 'Someone') + ' mentioned you in a post',
                                preview: (postText || '').substring(0, 80),
                                postId: postId || '',
                                read: false,
                                createdAt: new Date().toISOString()
                            }).catch(function(){});
                            // If target is current user → show immediate push notification
                            if (typeof userState !== 'undefined' && userState && targetDoc.id === userState.id) {
                                if (typeof window.pushNotification === 'function') {
                                    window.pushNotification('📣 You were mentioned by @' + (posterName || 'someone'), 'info');
                                }
                            }
                        }).catch(function(){});
                }
                if (typeof window._notifyMentionedUser !== 'function') window._notifyMentionedUser = _notifyMentionedUser;

                // ── Process tags from any post text ──
                // Called by post submit handlers after text is ready
                if (typeof window._processPostTags !== 'function') window._processPostTags = function(text, posterName, postId) {
                    if (!text) return;
                    // Extract @mentions
                    var mentions = text.match(/(?:^|[\s\n])@([a-zA-Z0-9_\.]+)/g) || [];
                    mentions.forEach(function(m) {
                        var uname = m.trim().replace('@', '');
                        if (uname) _notifyMentionedUser(uname, text, posterName, postId);
                    });
                    // Extract #hashtags and boost trending
                    var tags = text.match(/(?:^|[\s\n])#([a-zA-Z0-9_]+)/g) || [];
                    tags.forEach(function(t) {
                        var tag = t.trim().replace('#', '');
                        if (tag) _incrementTag(tag);
                    });
                };

                // ── Render the trending widget in the sidebar/dashboard ──
                function _renderTrendingWidget() {
                    var container = document.getElementById('_trending_widget_list');
                    if (!container) return;
                    var sorted = Object.entries(window._trendingTags)
                        .sort(function(a, b) { return b[1] - a[1]; })
                        .slice(0, 8);
                    if (sorted.length === 0) {
                        container.innerHTML = '<p style="font-size:0.8rem;color:#888;padding:8px 0;">No trending tags yet.</p>';
                        return;
                    }
                    container.innerHTML = sorted.map(function(entry, i) {
                        var tag = entry[0], score = entry[1];
                        return '<div class="_trend_item" data-tag="' + tag + '" style="'
                            + 'display:flex;align-items:center;justify-content:space-between;'
                            + 'padding:8px 0;border-bottom:1px solid rgba(10,14,39,0.06);cursor:pointer;">'
                            + '<div>'
                            + '<span style="font-size:0.72rem;color:#aaa;">' + (i+1) + ' · Trending</span><br>'
                            + '<strong style="font-size:0.9rem;color:var(--primary);">#' + tag + '</strong>'
                            + '</div>'
                            + '<span style="font-size:0.75rem;color:#888;background:rgba(27,43,139,0.08);padding:2px 8px;border-radius:20px;">'
                            + score + ' post' + (score !== 1 ? 's' : '') + '</span>'
                            + '</div>';
                    }).join('');
                    // Click a trending tag → filter feed
                    container.querySelectorAll('._trend_item').forEach(function(el) {
                        el.addEventListener('click', function() {
                            var tag = el.dataset.tag;
                            _incrementTag(tag); // each click boosts it slightly
                            // Simulate hashtag-tag click to filter the feed
                            document.querySelectorAll('.hashtag-tag').forEach(function(ht) {
                                if (ht.dataset.tag && ht.dataset.tag.toLowerCase() === tag) {
                                    ht.click(); return;
                                }
                            });
                            // Scroll to first matching post
                            var matched = Array.from(document.querySelectorAll('.story-content, .news-item-content'))
                                .filter(function(el) { return el.textContent.toLowerCase().includes('#' + tag); });
                            if (matched.length > 0) {
                                matched[0].closest('.impact-story, .news-list-item, article') ?
                                    matched[0].closest('.impact-story, .news-list-item, article').scrollIntoView({ behavior: 'smooth', block: 'center' }) :
                                    matched[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
                                if (typeof showNotification === 'function') showNotification('#' + tag + ' -- ' + matched.length + ' matching post(s)', 'info');
                            } else {
                                if (typeof showNotification === 'function') showNotification('#' + tag + ' -- No posts found yet', 'info');
                            }
                        });
                    });
                }
                window._renderTrendingWidget = _renderTrendingWidget;

                // ── Inject trending widget into the dashboard sidebar ──
                // Will auto-place itself in #right-sidebar or after the suggested-users section
                function _injectTrendingWidget() {
                    if (document.getElementById('_trending_widget')) return;
                    var widget = document.createElement('div');
                    widget.id = '_trending_widget';
                    widget.style.cssText = 'background:white;border-radius:20px;padding:16px;margin-bottom:16px;box-shadow:0 2px 16px rgba(10,14,39,0.07);border:1px solid rgba(10,14,39,0.07);';
                    widget.innerHTML = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">'
                        + '<svg width="19" height="19" viewBox="0 0 20 20" style="flex-shrink:0;filter:drop-shadow(0 1px 3px rgba(255,87,34,0.32));">'
                        + '<defs><linearGradient id="_trendFlameGrad" x1="0%" y1="0%" x2="100%" y2="100%">'
                        + '<stop offset="0%" stop-color="var(--color-flame,#FF5722)"/>'
                        + '<stop offset="100%" stop-color="var(--color-flame-light,#FFAB40)"/>'
                        + '</linearGradient></defs>'
                        + '<path fill="url(#_trendFlameGrad)" fill-rule="evenodd" clip-rule="evenodd" d="M12.963 2.286a.75.75 0 0 0-1.071-.136 9.742 9.742 0 0 0-3.539 6.176 7.547 7.547 0 0 1-1.705-1.715.75.75 0 0 0-1.152-.082A9 9 0 1 0 15.68 4.534a7.46 7.46 0 0 1-2.717-2.248ZM15.75 14.25a3.75 3.75 0 1 1-7.313-1.172c.628.465 1.35.81 2.133 1a5.99 5.99 0 0 1 1.925-3.545 3.75 3.75 0 0 1 3.255 3.717Z"/>'
                        + '</svg>'
                        + '<strong style="font-size:0.92rem;font-weight:700;letter-spacing:0.01em;color:var(--primary);">Trending</strong>'
                        + '</div>'
                        + '<div id="_trending_widget_list"></div>';
                    // Try to place in right sidebar first, then suggested users container
                    var sidebar = document.getElementById('right-sidebar')
                        || document.getElementById('suggested-users-container')?.parentElement
                        || document.querySelector('.sidebar-right, .right-col, [class*="right-sidebar"]');
                    if (sidebar) {
                        sidebar.insertBefore(widget, sidebar.firstChild);
                    } else {
                        // Append to dashboard as fallback
                        var dash = document.getElementById('dashboard');
                        if (dash) dash.appendChild(widget);
                    }
                    _renderTrendingWidget();
                }
                // Defer so DOM is ready
                setTimeout(_injectTrendingWidget, 800);
                // Re-inject on section change
                document.addEventListener('empyrean:sectionchange', function() {
                    setTimeout(function() { _injectTrendingWidget(); _renderTrendingWidget(); }, 300);
                });

                // ── Real-time trending listener from Firestore ──
                function _startTrendingListener() {
                    if (typeof fbDb === 'undefined' || !fbDb || window._trendingListener) return;
                    window._trendingListener = fbDb.collection('trending_tags')
                        .orderBy('score', 'desc').limit(20)
                        .onSnapshot(function(snap) {
                            snap.forEach(function(doc) {
                                window._trendingTags[doc.id] = doc.data().score || 0;
                            });
                            _renderTrendingWidget();
                        }, function(err) { console.warn('[Trending] listener error:', err); });
                }
                setTimeout(_startTrendingListener, 2000);

                console.log('[TagEngine] @mention notifications + #hashtag trending initialised');
            })();


                        function handleYoutubeEmbed(text) {
                const youtubeRegex = /(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu.be\/)([a-zA-Z0-9_-]{11})/;
                const match = text.match(youtubeRegex);
                if (match && match[1]) {
                    const videoId = match[1];
                    const embedHTML = `<div class="story-youtube-embed"><iframe src="https://www.youtube.com/embed/${videoId}" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>`;
                    return { html: text.replace(youtubeRegex, embedHTML), found: true };
                }
                return { html: `<p>${formatWhatsAppText(text)}</p>`, found: false };
            }

            function resizeAndCropImage(file, width, height, callback) {
                const reader = new FileReader();
                reader.onload = (e) => {
                    const img = new Image();
                    img.onload = () => {
                        const canvas = document.createElement('canvas');
                        const ctx = canvas.getContext('2d');
                        canvas.width = width;
                        canvas.height = height;

                        let sourceX, sourceY, sourceWidth, sourceHeight;
                        const imgRatio = img.width / img.height;
                        const targetRatio = width / height;

                        if (imgRatio > targetRatio) {
                            sourceHeight = img.height;
                            sourceWidth = sourceHeight * targetRatio;
                            sourceX = (img.width - sourceWidth) / 2;
                            sourceY = 0;
                        } else {
                            sourceWidth = img.width;
                            sourceHeight = sourceWidth / targetRatio;
                            sourceY = (img.height - sourceHeight) / 2;
                            sourceX = 0;
                        }
                        
                        ctx.drawImage(img, sourceX, sourceY, sourceWidth, sourceHeight, 0, 0, width, height);
                        callback(canvas.toDataURL('image/jpeg'));
                    };
                    img.src = e.target.result;
                };
                reader.readAsDataURL(file);
            }

            function handleAvatarUpload(file, previewId, isProfilePic = false, onDone) {
                const preview = document.getElementById(previewId);
                if (!preview) return;

                if (!file) { 
                    preview.src = '';
                    preview.classList.remove('active');
                    // Show upload icon if it exists
                    const uploadIcon = preview.nextElementSibling;
                    if (uploadIcon && uploadIcon.classList.contains('upload-icon')) {
                        uploadIcon.style.opacity = 1;
                    }
                    return;
                }

                const displayImage = (dataUrl) => {
                    preview.src = dataUrl;
                    if (!preview.classList.contains('active')) preview.classList.add('active');
                     // Hide upload icon
                    const uploadIcon = preview.nextElementSibling;
                    if (uploadIcon && uploadIcon.classList.contains('upload-icon')) {
                        uploadIcon.style.opacity = 0;
                    }
                };
                
                if (isProfilePic) {
                    resizeAndCropImage(file, 150, 150, (dataUrl) => {
                        if (previewId === 'avatar-preview') newAvatarFile = dataUrl; // For signup form
                        if (previewId === 'profile-pic-img') newAvatarFile = dataUrl; // For main profile
                        displayImage(dataUrl);
                        if (typeof onDone === 'function') onDone(dataUrl);
                    });
                } else {
                     const reader = new FileReader();
                    reader.onload = (e) => displayImage(e.target.result);
                    reader.readAsDataURL(file);
                }
            }

            /* AUTOSAVE — profile photo / cover photo, no Save button required.
               FIX (request: "enable click profile and cover automatic upload
               without clicking any button"): previously, choosing a new avatar
               or cover photo only staged it into newAvatarFile/newCoverFile and
               showed a local preview -- the actual Cloudinary/Firebase Storage
               upload + Firestore write only happened later, when the user
               separately submitted the #profile-info-form (the profile page's
               Save button). That's also where the "Unsupported field value: a
               custom Set object (found in field downloadedPostIds...)" crash in
               the console was surfacing: userState.downloadedPostIds is a Set
               and the whole write aborted if the Set->Array conversion this
               went through wasn't kept in sync (see app-auth.js's SET_KEYS /
               generic-Set-sweep fix). This reuses that exact same, already-
               fixed saveUserToFirestore() (never a raw fbDb.set() call here),
               so the Set-conversion fix keeps covering this path too, and just
               moves the upload+save to fire the instant a file is chosen,
               instead of waiting on a separate submit. Only wired to the two
               inputs on the logged-in user's own profile page
               (profile-pic-input-main / cover-photo-input) -- NOT to
               signup-avatar, which runs before any uid/account exists. */
            async function autoSaveProfileMedia(kind, dataUrl) {
                if (typeof isGuest !== 'undefined' && isGuest) return; // guest: local preview only, nothing to persist yet
                if (!userState || !userState.id) return;
                const isAvatar = kind === 'avatar';
                showNotification(isAvatar ? 'Uploading profile photo...' : 'Uploading cover photo...', 'info');
                try {
                    let cloudUrl = dataUrl;
                    try {
                        const res = await fetch(dataUrl);
                        const blob = await res.blob();
                        const f = new File([blob], (isAvatar ? 'avatar.jpg' : 'cover.jpg'), { type: 'image/jpeg' });
                        cloudUrl = await window.uploadToCloudinary(f, null);
                    } catch (upErr) {
                        // Persistent data: URL fallback (never a blob: URL --
                        // those don't survive a refresh or another device),
                        // same fallback the manual-save path already used.
                        cloudUrl = dataUrl;
                    }

                    if (isAvatar) { userState.avatar = cloudUrl; newAvatarFile = null; }
                    else { userState.coverPhoto = cloudUrl; newCoverFile = null; }

                    var _cloudSaved = true;
                    if (userState.id && !userState.id.startsWith('user-demo')) {
                        // FIX (2026-08-06 — "Missing or insufficient permissions"
                        // right after a successful Storage upload): this used to
                        // pass the WHOLE userState object here, so a simple photo
                        // change re-sent every field on the profile -- including
                        // empyBalance and the staking fields (manualStakedBalance,
                        // lockedStakedBalance, etc.). firebase-rules.js's owner
                        // rule for /users/{userId} rejects ANY update that even
                        // looks like it touches those fields (isSelfEmpyBalance-
                        // NonIncreasing / touchesServerOnlyStakingFields), even
                        // when the value is unchanged -- e.g. a Timestamp field
                        // that round-tripped through localStorage/JSON along the
                        // way no longer looks like the same type Firestore has on
                        // record, which reads as "touched." Sending ONLY the one
                        // field that actually changed avoids the whole class of
                        // false positives, and is also just the correct-sized
                        // write for what this action is doing.
                        var _mediaUpdate = isAvatar ? { avatar: cloudUrl } : { coverPhoto: cloudUrl };
                        _cloudSaved = await saveUserToFirestore(userState.id, _mediaUpdate);
                    }
                    try {
                        const stored = JSON.parse(localStorage.getItem('empyrean_users') || '{}');
                        const safe = { ...userState };
                        ['likedPostIds','followedUserIds','retweetedPostIds','downloadedPostIds','quotedPostIds','awardedRanks','completedTasks','viewedStatusUserIds']
                            .forEach(k => { if (safe[k] instanceof Set) safe[k] = [...safe[k]]; });
                        delete safe.password;
                        stored[userState.email] = safe;
                        localStorage.setItem('empyrean_users', JSON.stringify(stored));
                    } catch (lsErr) {}

                    if (isAvatar && typeof propagateProfilePicture === 'function') propagateProfilePicture();
                    if (typeof renderUserProfile === 'function') renderUserProfile(userState.id);

                    showNotification(
                        _cloudSaved
                            ? (isAvatar ? '✅ Profile photo saved!' : '✅ Cover photo saved!')
                            : (isAvatar ? 'Profile photo saved locally -- will sync when back online.' : 'Cover photo saved locally -- will sync when back online.'),
                        _cloudSaved ? 'success' : 'warning'
                    );
                } catch (err) {
                    console.error('Auto profile media save error:', err);
                    showNotification((isAvatar ? 'Profile photo' : 'Cover photo') + ' updated locally (cloud sync failed).', 'warning');
                }
            }
            
            function handleMediaPreview(files, previewContainerId) {
                const previewContainer = document.getElementById(previewContainerId);
                if (!previewContainer) return;
                previewContainer.innerHTML = '';

                const fileArr = Array.from(files);
                const count = fileArr.length;

                // Premium multi-image grid layout based on count
                previewContainer.style.display = 'grid';
                previewContainer.style.gap = '4px';
                previewContainer.style.borderRadius = '14px';
                previewContainer.style.overflow = 'hidden';
                if (count === 1)      previewContainer.style.gridTemplateColumns = '1fr';
                else if (count === 2) previewContainer.style.gridTemplateColumns = '1fr 1fr';
                else if (count === 3) previewContainer.style.gridTemplateColumns = '2fr 1fr';
                else if (count >= 4)  previewContainer.style.gridTemplateColumns = '1fr 1fr';
                else                  previewContainer.style.gridTemplateColumns = 'repeat(auto-fill, minmax(90px, 1fr))';

                fileArr.forEach((file, idx) => {
                    const url = URL.createObjectURL(file);
                    const mediaWrapper = document.createElement('div');
                    mediaWrapper.style.cssText = 'position:relative;overflow:hidden;background:#f0f0f0;';
                    // Special layout for 3-image: first spans 2 rows
                    if (count === 3 && idx === 0) {
                        mediaWrapper.style.gridRow = '1 / 3';
                    }
                    mediaWrapper.style.height = count === 1 ? '240px' : '160px';

                    let mediaElement;
                    if (file.type.startsWith('image/')) {
                        mediaElement = document.createElement('img');
                        mediaElement.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block;';
                    } else if (file.type.startsWith('video/')) {
                        mediaElement = document.createElement('video');
                        mediaElement.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block;';
                        mediaElement.controls = true;
                        mediaElement.muted = true;
                        mediaElement.loop = true;
                        mediaElement.autoplay = true;
                    }

                    // File count badge if more than 4 files
                    if (count > 4 && idx === 3) {
                        const badge = document.createElement('div');
                        badge.style.cssText = 'position:absolute;inset:0;background:rgba(10,14,39,0.6);display:flex;align-items:center;justify-content:center;color:white;font-size:1.5rem;font-weight:800;font-family:Syne,sans-serif;';
                        badge.textContent = '+' + (count - 4);
                        mediaWrapper.appendChild(badge);
                    }

                    if (mediaElement) {
                        mediaElement.src = url;
                        mediaWrapper.appendChild(mediaElement);
                    }
                    // Remove button
                    const removeBtn = document.createElement('button');
                    removeBtn.style.cssText = 'position:absolute;top:5px;right:5px;background:rgba(239,68,68,0.85);border:none;color:white;border-radius:50%;width:22px;height:22px;font-size:0.75rem;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;z-index:3;';
                    removeBtn.innerHTML = '×';
                    removeBtn.type = 'button';
                    removeBtn.addEventListener('click', function() {
                        mediaWrapper.remove();
                    });
                    mediaWrapper.appendChild(removeBtn);

                    previewContainer.appendChild(mediaWrapper);
                    if (count > 4 && idx >= 4) mediaWrapper.style.display = 'none'; // hide extras
                });
            }
            
            // FIX (request — "uploaded files should display according to
            // their type"): lightweight chip-list preview for the
            // "Upload documents" input, distinct from handleMarketplacePreview
            // (which is a photo/video grid) — a résumé/certificate upload
            // isn't a photo grid, so this shows a small type-labeled chip
            // per selected file (PDF / DOC / image thumbnail) with its own
            // remove button, mirroring the type-aware rendering
            // app-marketplace.js's window._mktDocumentsHTML uses once the
            // listing is actually posted, so what a seller sees while
            // selecting matches what a buyer later sees on the card.
            function handleMarketplaceDocPreview(filesArray, previewContainer) {
                if (!previewContainer) return;
                if (!filesArray || filesArray.length === 0) { previewContainer.innerHTML = ''; return; }
                var kindOf = (typeof window._mktFileKind === 'function') ? window._mktFileKind : function (name) {
                    var ext = String(name || '').split('.').pop().toLowerCase();
                    if (ext === 'pdf') return 'pdf';
                    if (ext === 'doc' || ext === 'docx') return 'doc';
                    if (/^(jpe?g|png|gif|webp|bmp|heic)$/.test(ext)) return 'image';
                    return 'other';
                };
                previewContainer.innerHTML = '';
                previewContainer.className = 'mkt-doc-list';
                Array.from(filesArray).forEach(function (file, idx) {
                    var kind = kindOf(file.name);
                    var chip = document.createElement('span');
                    chip.className = 'mkt-doc-chip' +
                        (kind === 'pdf' ? ' mkt-doc-chip-pdf' : kind === 'doc' ? ' mkt-doc-chip-doc' : kind === 'image' ? ' mkt-doc-chip-img' : ' mkt-doc-chip-doc');
                    if (kind === 'image') {
                        var img = document.createElement('img');
                        img.src = URL.createObjectURL(file);
                        img.alt = file.name || 'Document';
                        chip.appendChild(img);
                    } else {
                        chip.innerHTML = '<i class="fas ' + (kind === 'pdf' ? 'fa-file-pdf' : 'fa-file-word') + '"></i> ' +
                            (kind === 'pdf' ? 'PDF' : kind === 'doc' ? 'DOC' : 'FILE');
                    }
                    var rm = document.createElement('button');
                    rm.type = 'button';
                    rm.className = 'remove-doc-btn';
                    rm.dataset.index = idx;
                    rm.setAttribute('aria-label', 'Remove this file');
                    rm.innerHTML = '&times;';
                    rm.style.cssText = 'position:absolute;top:-6px;right:-6px;width:18px;height:18px;border-radius:50%;background:rgba(10,14,39,0.85);color:#fff;border:none;font-size:0.7rem;line-height:1;cursor:pointer;';
                    chip.style.position = 'relative';
                    chip.appendChild(rm);
                    previewContainer.appendChild(chip);
                });
            }

            function handleMarketplacePreview(filesArray, previewContainer) {
                if (!previewContainer) return;
                if (!filesArray || filesArray.length === 0) { previewContainer.innerHTML = ''; return; }
                previewContainer.innerHTML = '';
                previewContainer.classList.add('mkt-preview-grid');
                var count = filesArray.length;
                var shown = Math.min(count, 4);
                previewContainer.style.display = 'grid';
                previewContainer.style.gap = '6px';
                previewContainer.style.borderRadius = '14px';
                previewContainer.style.overflow = 'hidden';
                previewContainer.style.marginTop = '8px';
                if (shown === 1) previewContainer.style.gridTemplateColumns = '1fr';
                else if (shown === 2) previewContainer.style.gridTemplateColumns = '1fr 1fr';
                else if (shown === 3) previewContainer.style.gridTemplateColumns = '2fr 1fr';
                else previewContainer.style.gridTemplateColumns = '1fr 1fr';

                /* Build a stable list of object URLs for this batch so the
                   fullscreen gallery can be opened on any of them, not just
                   the visibly-rendered first 4. Re-used for each cell tap. */
                var galleryUrls = Array.from(filesArray).map(function (file) {
                    var url = (typeof file === 'string') ? file : URL.createObjectURL(file);
                    var type = (typeof file === 'string') ? (file.match(/\.(mp4|webm|mov)/i) ? 'video/mp4' : 'image/jpeg')
                                                            : (file.type || '');
                    return { url: url, type: type };
                });

                Array.from(filesArray).forEach(function (file, idx) {
                    if (idx >= 4) return;
                    var url  = galleryUrls[idx].url;
                    var type = galleryUrls[idx].type;
                    var isVid = type.startsWith('video') || /\.(mp4|webm|mov)/i.test(url);

                    var cell = document.createElement('div');
                    cell.className = 'mkt-preview-cell';
                    cell.dataset.index = idx;
                    var h = shown === 1 ? '240px' : '150px';
                    cell.style.cssText = 'height:' + h + ';' + (shown === 3 && idx === 0 ? 'grid-row:1/3;' : '');

                    cell.innerHTML = isVid
                        ? '<video src="' + url + '" class="mkt-preview-media" muted playsinline preload="metadata"></video>'
                            + '<div class="mkt-preview-playicon"><i class="fas fa-play"></i></div>'
                        : '<img src="' + url + '" class="mkt-preview-media" loading="lazy" alt="Upload preview">';

                    cell.innerHTML += '<div class="mkt-preview-zoomhint"><i class="fas fa-expand"></i></div>';

                    var removeBtn = document.createElement('button');
                    removeBtn.type = 'button';
                    removeBtn.className = 'remove-media-btn mkt-preview-remove';
                    removeBtn.dataset.index = idx;
                    removeBtn.setAttribute('aria-label', 'Remove this item');
                    removeBtn.innerHTML = '&times;';
                    cell.appendChild(removeBtn);

                    if (count > 4 && idx === 3) {
                        var badge = document.createElement('div');
                        badge.className = 'mkt-preview-overflow';
                        badge.textContent = '+' + (count - 3);
                        cell.appendChild(badge);
                    }

                    /* Tap anywhere on the cell (but not the remove button)
                       opens the existing fullscreen gallery lightbox at this
                       index, reusing showMarketplaceGallery so prev/next,
                       thumbnails, keyboard nav and swipe all work exactly
                       like the rest of the app. */
                    cell.addEventListener('click', function (e) {
                        if (e.target.closest('.mkt-preview-remove')) return;
                        if (typeof window.showMarketplaceGallery === 'function') {
                            window.showMarketplaceGallery(galleryUrls, idx);
                        }
                    });

                    previewContainer.appendChild(cell);
                });
            }

            function createMessageElement(text, isSent, isFile = false, fileUrl = '', fileType = '', messageId = `msg-${Date.now()}`) {
                const messageEl = document.createElement('div');
                messageEl.className = `message ${isSent ? 'sent' : 'received'}`;
                messageEl.dataset.messageId = messageId; 
                
                let contentHTML = '';
                if (isFile) {
                    if (fileType.startsWith('image/')) {
                        contentHTML = `<p>${text}</p><img src="${fileUrl}" class="message-media" alt="Sent image">`;
                    } else if (fileType.startsWith('video/')) {
                        contentHTML = `<p>${text}</p><video src="${fileUrl}" class="message-media" controls></video>`;
                    } else if (fileType.startsWith('audio/')) { 
                        contentHTML = `<p>${text}</p><audio src="${fileUrl}" class="message-media" controls></audio>`;
                    } else {
                         contentHTML = `<p><i class="fas fa-file-alt"></i> Sent a file: <a href="${fileUrl}" target="_blank">${text}</a></p>`;
                    }
                } else {
                    contentHTML = formatWhatsAppText(text);
                }
                
                messageEl.innerHTML = contentHTML;
                return messageEl;
            }


            // Expose shareContent globally so business page inline onclick works
            window.shareContent = shareContent;


            // --- LIVE STREAM FUNCTIONS ---
            function populateBackgroundSelector() {
                const container = document.getElementById('live-bg-selector');
                if (!container) return;
                container.innerHTML = '';

                // Group by category
                const categories = { classic: 'Classic', premium: 'Premium', studio: 'Studio', photo: 'Photo' };
                const grouped = {};
                liveBackgrounds.forEach(bg => {
                    if (!grouped[bg.category]) grouped[bg.category] = [];
                    grouped[bg.category].push(bg);
                });

                Object.entries(categories).forEach(([cat, catLabel]) => {
                    if (!grouped[cat]) return;
                    const catHeader = document.createElement('div');
                    catHeader.style.cssText = 'width:100%;font-size:0.7rem;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--text-muted);padding:8px 2px 4px;flex-basis:100%;';
                    catHeader.textContent = catLabel;
                    container.appendChild(catHeader);

                    grouped[cat].forEach(bg => {
                        const isPhoto = bg && bg.style && typeof bg.style === 'string' && bg.style.startsWith('http');
                        const thumb = document.createElement('div');
                        thumb.className = `bg-thumb ${liveStreamData.background === bg.style ? 'active' : ''}`;
                        thumb.dataset.bg = bg.style;
                        thumb.title = bg.label;
                        if (isPhoto) {
                            thumb.style.backgroundImage = `url(${bg.style})`;
                            thumb.style.backgroundSize = 'cover';
                            thumb.style.backgroundPosition = 'center';
                        } else {
                            thumb.style.background = bg.style;
                        }
                        // Label overlay
                        const lbl = document.createElement('span');
                        lbl.style.cssText = 'position:absolute;bottom:4px;left:0;right:0;text-align:center;font-size:0.55rem;color:rgba(255,255,255,0.9);text-shadow:0 1px 3px rgba(0,0,0,0.7);font-weight:600;letter-spacing:0.3px;';
                        lbl.textContent = bg.label;
                        thumb.style.position = 'relative';
                        thumb.appendChild(lbl);
                        container.appendChild(thumb);
                    });
                });

                if (liveStreamData.customBackgroundFile) {
                    const customBgUrl = URL.createObjectURL(liveStreamData.customBackgroundFile);
                    const customThumb = document.createElement('div');
                    customThumb.className = `bg-thumb ${liveStreamData.background === customBgUrl ? 'active' : ''}`;
                    customThumb.dataset.bg = customBgUrl;
                    customThumb.style.backgroundImage = `url(${customBgUrl})`;
                    customThumb.style.backgroundSize = 'cover';
                    const lbl = document.createElement('span');
                    lbl.style.cssText = 'position:absolute;bottom:4px;left:0;right:0;text-align:center;font-size:0.55rem;color:white;font-weight:600;';
                    lbl.textContent = 'Custom';
                    customThumb.style.position = 'relative';
                    customThumb.appendChild(lbl);
                    container.prepend(customThumb);
                }
            }

            function populateGiftCatalog() {
                const container = document.getElementById('gift-grid-container');
                if (!container) return;
                container.innerHTML = '';
                empyGiftCatalog.forEach(gift => {
                    const giftEl = document.createElement('div');
                    giftEl.className = 'gift-item';
                    giftEl.dataset.name = gift.name;
                    giftEl.dataset.symbol = gift.symbol;
                    giftEl.dataset.price = gift.price;
                    giftEl.dataset.tier = gift.tier || (gift.price >= 1000 ? 'legendary' : gift.price >= 120 ? 'epic' : gift.price >= 25 ? 'rare' : 'basic');
                    giftEl.innerHTML = `<div class="symbol">${gift.symbol}</div><div class="name">${gift.name}</div><div class="price"><i class="fa-solid fa-coins"></i> ${gift.price}</div>`;
                    container.appendChild(giftEl);
                });
            }
            
            function showGiftAnimation(symbol, giftName) {
                const layer = document.getElementById('gift-animation-layer');
                if (!layer) return;

                // FIX (bug: "rose still shows the gear-ball orb icon when sent
                // from the catalog"): every call site here (the full-catalog
                // send in _empySendGiftNowInner below, the one-tap quick-Rose
                // button in app-live-tiktok-patch.js, and the remote gift-sync
                // replay listener) passes gift.symbol straight from
                // window.empyGiftCatalog, which for Rose is a premium SVG
                // "orb" glyph, not the user-supplied rose image. There used to
                // be a fix for this, but it only wrapped window.createLiveGiftComment
                // (the chat-row renderer) — this function, the one that
                // actually draws the floating animation, was never patched,
                // so the orb kept showing up in the animation every time,
                // regardless of which button triggered the send. Swapping it
                // here, at the true source, catches every call path at once.
                if (giftName === 'Rose' && window.TK_ROSE_IMG) {
                    symbol = '<img class="tk-rose-img" src="' + window.TK_ROSE_IMG + '" alt="Rose">';
                }

                // FIX: symbol is now SVG icon markup (unified catalog), not a
                // plain emoji character, so the old `symbol === '💖'` check for
                // Heart Mills would never match — detect by gift name instead.
                if (giftName === 'Heart Mills') {
                    showHeartMillsAnimation();
                } else {
                    const animationEl = document.createElement('div');
                    animationEl.className = 'gift-animation';

                    // PATCH (session 2026-07-19) — reduce floating magnification
                    // for cheaper gifts, and give the Empy Token coin a
                    // transparent (no-background) float. Looks the gift up in
                    // the same catalog populateGiftCatalog() already reads
                    // (window.empyGiftCatalog), using the exact tier thresholds
                    // that function already applies (>=1000 legendary, >=120
                    // epic, >=25 rare, else basic) so this can't drift out of
                    // sync with that logic. Only acts when the lookup actually
                    // finds the gift by name — anything it can't confidently
                    // classify (unknown/custom gift name) keeps the original
                    // floatUpAndFade animation exactly as before, unchanged.
                    const _giftCatalogForAnim = window.empyGiftCatalog || empyGiftCatalog;
                    const _giftEntryForAnim = _giftCatalogForAnim && _giftCatalogForAnim.find(g => g.name === giftName);
                    if (_giftEntryForAnim) {
                        const _tierForAnim = _giftEntryForAnim.tier || (_giftEntryForAnim.price >= 1000 ? 'legendary' : _giftEntryForAnim.price >= 120 ? 'epic' : _giftEntryForAnim.price >= 25 ? 'rare' : 'basic');
                        if (_tierForAnim === 'basic' || _tierForAnim === 'rare') {
                            animationEl.classList.add('gift-animation-small');
                        }
                    }
                    // Token detection is based on what's actually in the
                    // markup (an <img> whose class names the token, e.g.
                    // tk-empy-token-img — see app-live-tiktok-patch.js), not
                    // the gift's display name, so it keeps working even if
                    // that name ever changes.
                    if (/class="[^"]*token[^"]*"/i.test(symbol || '') || /empy.?token/i.test(giftName || '')) {
                        animationEl.classList.add('gift-animation-token');
                    }

                    animationEl.innerHTML = symbol; // symbol is SVG markup, not plain text
                    animationEl.dataset.giftName = giftName || '';

                    // PATCH (session 2026-07-19, seventh follow-up) — "move the
                    // display position to the 4th avatar, let it drift and
                    // displayed at the 4th avatar horizontally": gifts
                    // originate from the vertical #tk-guestbox-stack (accepted
                    // guests only — see app-live-tiktok-patch.js) instead of a
                    // random spot along the bottom of the screen, using
                    // getBoundingClientRect() on both the layer and the tile
                    // to convert the tile's on-screen position into a
                    // top/left the layer's own absolutely-positioned children
                    // understand.
                    //
                    // FIX (session 2026-07-19, eighth follow-up — reported:
                    // "should display at the 4th avatar position so everyone
                    // can see it, but it's not; floats at the bottom, host
                    // might not even notice"): the ACTUAL bug this session —
                    // this only ever picked _gbTiles[3] (the literal 4th
                    // tile), which only exists when 4 people are
                    // SIMULTANEOUSLY accepted guests in #tk-guestbox-stack.
                    // #tk-guestbox-stack only ever holds accepted GUESTS, never
                    // the host, so a solo-host stream (host + 0 guests — the
                    // overwhelmingly common case, confirmed in this session's
                    // screenshot showing "1" participant) can never have a
                    // 4th tile at all, and silently fell all the way back to
                    // the old random-bottom placement every single time —
                    // exactly the "floats at the bottom, easy to miss" bug
                    // reported. The actual goal ("everyone can easily see it,
                    // host won't miss it") only needs SOME visible avatar
                    // anchor, not specifically the 4th — so the fallback
                    // chain now degrades gracefully instead of failing shut:
                    //   1) the 4th guest tile, if 4+ guests are in the stack
                    //      (preserves the original ask exactly, when possible)
                    //   2) otherwise the LAST guest tile currently in the
                    //      stack (1-3 guests) — still a real, visible avatar,
                    //      just not literally the 4th slot
                    //   3) otherwise (zero guests — solo host) the host's own
                    //      avatar badge (#live-host-avatar, top-left header —
                    //      see app-live-tiktok-patch.js), which is always
                    //      on-screen and is exactly where the host is already
                    //      looking, so the host can no longer miss it
                    //   4) only if NONE of the above exist in the DOM (should
                    //      not happen in practice) does this fall back to the
                    //      original random-bottom placement, same as before.
                    // Tier still decides how it moves from wherever it starts
                    // (small tiers get the horizontal drift via
                    // .gift-animation-small's giftFloatSmall/giftFloatSmallLeft
                    // keyframes above; everything else keeps its normal
                    // vertical giftFloat rise) — only where it starts from
                    // changes here.
                    const _gbTiles = document.querySelectorAll('#tk-guestbox-stack .tk-guestbox');
                    const _guestTile = _gbTiles[3] || _gbTiles[_gbTiles.length - 1] || null;
                    const _hostAvatarFallback = !_guestTile ? document.getElementById('live-host-avatar') : null;
                    const _anchorTile = _guestTile || _hostAvatarFallback;
                    if (_anchorTile) {
                        const layerRect = layer.getBoundingClientRect();
                        const tileRect = _anchorTile.getBoundingClientRect();
                        const topPx = (tileRect.top - layerRect.top) + (tileRect.height / 2) - 22; // roughly centered on the tile, minus half the (now 45px) gift box
                        // Guest-box tiles sit near the right edge and drift
                        // left, so starting 50px to the tile's LEFT reads
                        // naturally. #live-host-avatar sits near the left
                        // edge and (below) drifts right, so it needs to
                        // start just past the badge's RIGHT edge instead —
                        // using the same left-side offset here would place
                        // it off-screen (negative x) before the animation
                        // even begins.
                        const leftPx = _hostAvatarFallback
                            ? (tileRect.right - layerRect.left) + 6
                            : (tileRect.left - layerRect.left) - 50;
                        animationEl.style.top = `${topPx}px`;
                        animationEl.style.left = `${leftPx}px`;
                        animationEl.style.bottom = 'auto';
                        if (_hostAvatarFallback) {
                            // #live-host-avatar sits top-LEFT (header badge —
                            // see screenshot), the mirror-image position from
                            // #tk-guestbox-stack's right-edge tiles. Forcing
                            // the SAME leftward drift .gift-animation-avatar-
                            // anchor uses for the guest-box case would send
                            // it straight off the left edge of the screen
                            // within a couple hundred ms. Distinct class so
                            // style.css can force the opposite (rightward)
                            // drift for this specific anchor instead.
                            animationEl.classList.add('gift-animation-host-anchor');
                        } else {
                            animationEl.classList.add('gift-animation-avatar-anchor');
                        }
                    } else {
                        const minLeft = 20; // % from left
                        const maxLeft = 80; // % from left
                        animationEl.style.left = `${Math.random() * (maxLeft - minLeft) + minLeft}%`;
                    }
                    layer.appendChild(animationEl);
                    setTimeout(() => animationEl.remove(), 3000);
                }
            }
            
            function showHeartMillsAnimation() {
                const layer = document.getElementById('gift-animation-layer');
                if (!layer) return;

                for (let i = 0; i < 20; i++) { // Spawn 20 hearts
                    const heart = document.createElement('span');
                    heart.className = 'heart-mill-animation';
                    heart.innerHTML = '<i class="fas fa-heart"></i>';
                    const startX = Math.random() * 100; // Random x position
                    const delay = Math.random() * 2000; // Random delay for staggered effect
                    
                    heart.style.left = `${startX}vw`;
                    heart.style.animationDelay = `${delay}ms`;
                    layer.appendChild(heart);
                    setTimeout(() => heart.remove(), 4000 + delay); 
                }
            }

            // FIX (feature — "after the first 3 chat let the message disappear
            // into cloud and scrollable upward and downward"): the list is
            // display:flex; flex-direction:column-reverse, so the newest
            // comment is always the LAST rendered child visually (nearest the
            // input box) even though it's `prepend`-ed as the first DOM node.
            // The 3 most recent stay fully opaque (was 4 — user asked for
            // fading to start one avatar sooner); anything older gets a
            // `.tk-comment-faded` class (see style.css) that fades it toward
            // transparent, TikTok-cloud style, while the list itself is
            // already overflow-y:auto so users can still scroll up/down to
            // read the faded history.
            function _refreshCommentFade(list) {
                if (!list) return;
                var children = list.children;
                for (var i = 0; i < children.length; i++) {
                    // children[0] is the newest (most recently prepended).
                    if (i < 3) children[i].classList.remove('tk-comment-faded');
                    else children[i].classList.add('tk-comment-faded');
                }
            }

            // FIX (bug: "chat isn't scrollable up/down"): createLiveComment()
            // and createLiveGiftComment() used to unconditionally force
            // `list.scrollTop = list.scrollHeight` on EVERY new message —
            // list is `flex-direction: column-reverse`, so that's the end
            // that shows the newest comment. That meant the instant anyone
            // scrolled up to read older/faded messages, the very next
            // message (which can arrive at any time in a live chat) yanked
            // the view straight back down, making the list feel like it
            // couldn't be scrolled at all. Now the auto-snap-to-newest only
            // fires when the person was already at (or within a small
            // tolerance of) the newest end BEFORE the new comment landed —
            // i.e. they weren't deliberately reading back through history.
            // If they had scrolled up, their position is left alone and
            // they can keep scrolling freely in both directions; the newest
            // message still lands in the DOM (and the fade fires) whether
            // or not the view follows it down.
            function _isPinnedToNewest(list) {
                if (!list) return true;
                var maxScroll = list.scrollHeight - list.clientHeight;
                if (maxScroll <= 0) return true; // nothing to scroll yet
                return (maxScroll - list.scrollTop) < 60; // small tolerance
            }

            function createLiveComment(username, text, messageId = `msg-${Date.now()}`, avatarUrl = '', isGift = false) {
                const list = document.getElementById('live-comments-list');
                if (!list) return;

                // Remove existing pinned message from general comments if it was there and is being repinned/newly pinned.
                if (liveStreamData.pinnedMessage && liveStreamData.pinnedMessage.id === messageId) {
                    const existingPinnedCommentEl = list.querySelector(`.live-comment[data-message-id="${messageId}"]`);
                    if (existingPinnedCommentEl) existingPinnedCommentEl.remove(); // Remove to re-add it as a truly pinned item if needed.
                }

                // FIX (feature): every comment now carries a small circular avatar
                // next to the text, TikTok-style, instead of a bare name+text block.
                // Falls back to a generic silhouette if no avatar URL is available
                // (e.g. a mock user with no photo set).
                const commentEl = document.createElement('div');
                commentEl.className = 'live-comment' + (isGift ? ' tk-gift-comment' : '');
                commentEl.dataset.messageId = messageId;
                const safeAvatar = avatarUrl || 'https://api.dicebear.com/7.x/initials/svg?seed=' + encodeURIComponent(username || '?');
                commentEl.innerHTML =
                    `<img class="live-comment-avatar" src="${safeAvatar}" alt="" loading="lazy">` +
                    `<div class="live-comment-body"><strong>${username}</strong><p>${formatWhatsAppText(text)}</p></div>`;

                // Add new comment
                const _wasPinnedToNewest = _isPinnedToNewest(list);
                list.prepend(commentEl);
                if (_wasPinnedToNewest) list.scrollTop = list.scrollHeight;

                // Check if this message should be visually pinned as well
                if (liveStreamData.pinnedMessage && liveStreamData.pinnedMessage.id === messageId) {
                    commentEl.classList.add('pinned-comment');
                }

                _refreshCommentFade(list);

                if (!isGuest && userState.id === liveStreamData.hostUserId) {
                    const existingMessageIndex = liveStreamData.sentMessages.findIndex(msg => msg.id === messageId);
                    if (existingMessageIndex === -1) { // Only add if it's a new unique message
                         liveStreamData.sentMessages.push({ id: messageId, username: username, content: text });
                    }
                }
            }

            // FIX (feature — exact TikTok-style gift row): a plain <p>-of-text
            // gift line ("Sent a Rose to X! 🌹") doesn't match how TikTok (or
            // the reference screenshot) actually shows gifts: avatar, name,
            // a small "sent {gift}" caption, and a bold gift icon + ×N
            // multiplier on the right that increments in place when the same
            // person sends the same gift again in a row, instead of stacking
            // a fresh line per tap. This is a separate function (rather than
            // folding more branches into createLiveComment) because the
            // increment-in-place behavior only makes sense for gifts, never
            // for text chat.
            function createLiveGiftComment(username, avatarUrl, giftSymbol, giftName, userId) {
                const list = document.getElementById('live-comments-list');
                if (!list) return;

                // FIX (bug: "rose still shows the gear-ball orb icon when
                // sent from the catalog"): _empySendGiftNowInner (below)
                // calls this function directly through the local closure
                // reference, not through window.createLiveGiftComment — so
                // the wrapper in app-live-tiktok-patch.js that swaps in the
                // Rose image never actually ran for that path (only for
                // callers that happened to go through window.*, like the
                // quick-Rose button). Doing the swap here, at the real
                // source, means every caller gets the correct icon
                // regardless of which reference they call it through.
                if (giftName === 'Rose' && window.TK_ROSE_IMG) {
                    // Markup only (no extra wrapper) -- the caller's own
                    // template already wraps giftSymbol in .tk-emoji-3d.
                    giftSymbol = '<img class="tk-rose-img" src="' + window.TK_ROSE_IMG + '" alt="Rose">';
                }

                const mostRecent = list.firstElementChild;
                if (mostRecent && mostRecent.classList.contains('tk-gift-comment') &&
                    mostRecent.dataset.giftSenderId === String(userId) &&
                    mostRecent.dataset.giftName === giftName) {
                    // Same person, same gift, still the newest line — bump the
                    // counter in place instead of adding a new row underneath.
                    const countEl = mostRecent.querySelector('.tk-gift-multiplier');
                    const next = (parseInt(mostRecent.dataset.giftCount, 10) || 1) + 1;
                    mostRecent.dataset.giftCount = String(next);
                    if (countEl) countEl.textContent = '×' + next;
                    mostRecent.classList.remove('tk-gift-pulse');
                    // eslint-disable-next-line no-unused-expressions
                    void mostRecent.offsetWidth; // restart the pulse animation
                    mostRecent.classList.add('tk-gift-pulse');
                    _refreshCommentFade(list);
                    return;
                }

                const messageId = `gift-${Date.now()}`;
                const commentEl = document.createElement('div');
                commentEl.className = 'live-comment tk-gift-comment';
                commentEl.dataset.messageId = messageId;
                commentEl.dataset.giftSenderId = String(userId);
                commentEl.dataset.giftName = giftName;
                commentEl.dataset.giftCount = '1';
                const safeAvatar = avatarUrl || 'https://api.dicebear.com/7.x/initials/svg?seed=' + encodeURIComponent(username || '?');
                commentEl.innerHTML =
                    `<img class="live-comment-avatar" src="${safeAvatar}" alt="" loading="lazy">` +
                    `<div class="live-comment-body"><strong>${username}</strong><span class="tk-gift-caption">sent ${giftName}</span></div>` +
                    `<div class="tk-gift-icon-count"><span class="tk-gift-emoji"><span class="tk-emoji-3d">${giftSymbol}</span></span><span class="tk-gift-multiplier">×1</span></div>`;

                const _wasPinnedToNewestGift = _isPinnedToNewest(list);
                list.prepend(commentEl);
                if (_wasPinnedToNewestGift) list.scrollTop = list.scrollHeight;
                _refreshCommentFade(list);
            }
            window.createLiveComment = createLiveComment;
            window.createLiveGiftComment = createLiveGiftComment;
            // FIX (bug: "gifts do not sync across multiple devices"): needed
            // so a gift someone ELSE sent can replay its animation on this
            // device too — see attachGiftSyncListener() in
            // app-live-tiktok-patch.js.
            window.showGiftAnimation = showGiftAnimation;

            function createDashboardLiveCard(streamId, title, hostName, avatarSrc, bg, hostId, hostUsername) {
                const slider = document.getElementById('dashboard-live-slider');
                if (!slider) return;

                // Remove existing card for this stream (avoid duplicates)
                const existing = slider.querySelector('[data-stream-id="' + streamId + '"]');
                if (existing) existing.remove();

                // Hide the "No live streams" placeholder
                const emptyEl = document.getElementById('live-slider-empty');
                if (emptyEl) emptyEl.style.display = 'none';

                // Channel name matches what Firestore stores and Agora uses
                const channelName = 'empyrean-' + streamId;

                const card = document.createElement('div');
                card.className = 'live-stream-preview-card join-live-btn';
                card.dataset.streamId    = streamId;
                card.dataset.hostId      = hostId;
                card.dataset.hostName    = hostName;
                // FIX: this function used to never set dataset.hostUsername at all (unlike
                // the equivalent _insertStreamCard() in app-live.js, used for OTHER devices'
                // stream cards), leaving it undefined for any card built through this path.
                card.dataset.hostUsername = hostUsername || '';
                card.dataset.hostAvatar  = avatarSrc || '';
                card.dataset.streamTitle = title;
                card.dataset.agoraChannel = channelName;  // viewers use this to join
                card.dataset.background  = bg || '';
                card.style.cssText = 'flex:0 0 180px;min-width:180px;height:220px;border-radius:18px;overflow:hidden;cursor:pointer;position:relative;flex-shrink:0;';

                const isImage = bg && (bg.startsWith('http') || bg.startsWith('blob:'));
                if (isImage) {
                    card.style.backgroundImage = 'url(' + bg + ')';
                    card.style.backgroundSize = 'cover';
                    card.style.backgroundPosition = 'center';
                } else {
                    card.style.background = bg || 'linear-gradient(160deg,#0A0E27,#1B2B8B)';
                }

                const avatar = avatarSrc ? '<img src="' + avatarSrc + '" style="width:30px;height:30px;border-radius:50%;object-fit:cover;border:2px solid white;flex-shrink:0;">' : '';
                card.innerHTML =
                    '<div style="position:absolute;inset:0;background:linear-gradient(transparent 35%,rgba(0,0,0,0.85));z-index:1;"></div>' +
                    '<div style="position:absolute;top:10px;left:10px;z-index:2;">' +
                        '<span style="background:rgba(239,68,68,0.92);color:white;padding:3px 10px;border-radius:50px;font-size:0.7rem;font-weight:700;display:inline-flex;align-items:center;gap:5px;">' +
                            '<i class="fas fa-circle" style="font-size:0.45rem;animation:fa-beat 1s infinite;"></i> LIVE' +
                        '</span>' +
                    '</div>' +
                    '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);z-index:2;background:rgba(239,68,68,0.8);color:white;padding:8px 18px;border-radius:50px;font-size:0.8rem;font-weight:700;white-space:nowrap;">▶ Join Live</div>' +
                    '<div style="position:absolute;bottom:0;left:0;right:0;padding:12px;z-index:2;display:flex;align-items:center;gap:8px;">' +
                        avatar +
                        '<div style="flex:1;min-width:0;">' +
                            '<strong style="display:block;color:white;font-size:0.83rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + hostName + '</strong>' +
                            '<span style="color:rgba(255,255,255,0.75);font-size:0.72rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;">' + title + '</span>' +
                        '</div>' +
                    '</div>';
                slider.prepend(card);
            }

            function removeDashboardLiveCard(streamId) {
                const slider = document.getElementById('dashboard-live-slider');
                if (!slider) return;
                const existing = slider.querySelector('[data-stream-id="' + streamId + '"]');
                if (existing) existing.remove();
                const emptyEl = document.getElementById('live-slider-empty');
                if (emptyEl && !slider.querySelector('.live-stream-preview-card')) emptyEl.style.display = '';
            }

            // ── NOTIFY FOLLOWERS THAT HOST IS LIVE ────────────────────────────────
            // FIX: this was CALLED from the go-live-form handler below
            // (window.notifyFriendsUserIsLive(...)) but was never defined anywhere in
            // the entire codebase — the `typeof window.notifyFriendsUserIsLive ===
            // 'function'` guard always evaluated false, so it silently did nothing on
            // every single "Go Live". Followers never got notified at all.
            //
            // There's no dedicated "followers of X" collection in this schema —
            // follows are stored as a followedUserIds array on each user's own doc
            // (see the follow/unfollow handler further down, which does
            // fbDb.collection('users').doc(uid).update({followedUserIds:[...]})).
            // So finding "who follows the host" means querying users where
            // followedUserIds array-contains the host's id.
            //
            // Writes one doc per follower into 'user_notifications' — the SAME
            // collection/schema already used (and proven working) for like/follow
            // notifications elsewhere in this file, which the onSnapshot listener at
            // "Subscribe to user_notifications for real-time dashboard updates" picks
            // up automatically (calls showNotification() + bumps the bell badge) for
            // any follower who has the app open, and shows up in their notifications
            // list next time they open it if not.
            window.notifyFriendsUserIsLive = function (hostName, streamId) {
                var db = window.fbDb;
                if (!db || typeof db.collection !== 'function') return;
                var hostId = (window.userState && window.userState.id) || null;
                if (!hostId) return;

                db.collection('users')
                    .where('followedUserIds', 'array-contains', hostId)
                    .get()
                    .then(function (snap) {
                        if (!snap || snap.empty) return;
                        var batch = db.batch();
                        var count = 0;
                        snap.forEach(function (doc) {
                            var followerId = doc.id;
                            if (!followerId || followerId === hostId) return;
                            var ref = db.collection('user_notifications').doc();
                            batch.set(ref, {
                                userId: followerId,
                                type: 'live',
                                message: '🔴 ' + (hostName || 'Someone') + ' just went live! Tap to join.',
                                fromUserId: hostId,
                                streamId: streamId || '',
                                read: false,
                                createdAt: new Date().toISOString()
                            });
                            count++;
                        });
                        if (count > 0) {
                            batch.commit().catch(function (e) {
                                console.warn('[Live] notifyFriendsUserIsLive batch commit failed:', e && e.message);
                            });
                        }
                    })
                    .catch(function (err) {
                        console.warn('[Live] notifyFriendsUserIsLive query failed:', err && err.message);
                    });
            };

            // ── NOTIFY FOLLOWERS OF NEW CONTENT (posts, reels, news, etc.) ────────
            // FIX (bug report: "notifications only appear for go live events, not
            // when someone makes a post" / "notifications do not cross-populate
            // across devices" for posts): notifyFriendsUserIsLive() directly above
            // is the ONLY content-creation event in this whole app that ever wrote
            // a 'user_notifications' doc for followers. Every other create-content
            // path (feed post, Quick Post FAB, reel upload, news article) never
            // notified anyone at all -- not in-app, not cross-device -- because
            // nothing called anything like this. This generalizes that exact same
            // proven mechanism (one doc per follower into 'user_notifications',
            // already picked up cross-device and in real time by the onSnapshot
            // listener at "Subscribe to user_notifications for real-time dashboard
            // updates" further down this file) so every content type can reuse it
            // instead of duplicating the follower query at every call site.
            //
            // authorId defaults to the CURRENT user (the normal case: someone
            // creates their own post) but can be passed explicitly for the one
            // case where the current user isn't the content's author -- an admin
            // approving someone else's SOS request, where the notification must
            // go to the SUBMITTER's followers, not the approving admin's.
            window._empNotifyFollowersOfContent = function (type, message, extra, authorId) {
                var db = window.fbDb;
                if (!db || typeof db.collection !== 'function') return;
                var aid = authorId || (window.userState && window.userState.id) || null;
                if (!aid) return;

                db.collection('users')
                    .where('followedUserIds', 'array-contains', aid)
                    .get()
                    .then(function (snap) {
                        if (!snap || snap.empty) return;
                        var batch = db.batch();
                        var count = 0;
                        snap.forEach(function (doc) {
                            var followerId = doc.id;
                            if (!followerId || followerId === aid) return;
                            var ref = db.collection('user_notifications').doc();
                            var payload = {
                                userId: followerId,
                                type: type,
                                message: message,
                                fromUserId: aid,
                                read: false,
                                createdAt: new Date().toISOString()
                            };
                            if (extra) {
                                for (var k in extra) { if (extra.hasOwnProperty(k)) payload[k] = extra[k]; }
                            }
                            batch.set(ref, payload);
                            count++;
                        });
                        if (count > 0) {
                            batch.commit().catch(function (e) {
                                console.warn('[Notify] ' + type + ' follower batch commit failed:', e && e.message);
                            });
                        }
                    })
                    .catch(function (err) {
                        console.warn('[Notify] ' + type + ' followers query failed:', err && err.message);
                    });
            };

            // ── LIVE STREAM DISCOVERY (real-time, cross-device) ──────────────────
            // Reads the 'live_streams' collection so any user's Go Live broadcast
            // shows up as a joinable card on every OTHER user's dashboard, not just
            // the host's own screen. Before this, createDashboardLiveCard() was only
            // ever called locally on the host's device — nothing was ever written to
            // or read from Firestore, so nobody else could discover a stream existed.
            let _liveStreamsUnsub = null;
            function syncLiveStreamsFromFirestore() {
                /* DISABLED — root cause of "other devices don't see live streams":
                   this function reads collection 'live_streams' (field status=='live'),
                   which is a COMPLETELY SEPARATE collection from the one app-live.js

                   actually publishes to and listens on ('active_streams', field
                   isLive==true — see window.publishLiveStreamToFirestore and
                   window.startLiveStreamListener in app-live.js). Two independent,
                   uncoordinated discovery systems existed side by side; only
                   'active_streams' is written to by the real Agora-confirmed publish
                   step, so this listener was watching an effectively empty/stale
                   collection on every device except the host's own (which always saw
                   its own card via the LOCAL createDashboardLiveCard() call below,
                   regardless of Firestore). Disabling this to make active_streams the
                   single source of truth. Do not re-enable without also removing the
                   duplicate 'live_streams' write further down in this same handler. */
                return;
                if (!window.fbDb || typeof window.fbDb.collection !== 'function') return;
                if (_liveStreamsUnsub) return; // already listening
                try {
                    _liveStreamsUnsub = window.fbDb.collection('live_streams')
                        .where('status', '==', 'live')
                        .onSnapshot(function (snap) {
                            const seenIds = new Set();
                            snap.forEach(function (doc) {
                                const d = doc.data() || {};
                                if (!d.streamId) return;
                                // Ignore stale streams (e.g. host crashed/closed tab without
                                // ever hitting "End Stream") older than 4 hours.
                                if (d.startedAtMs && (Date.now() - d.startedAtMs) > 4 * 60 * 60 * 1000) return;
                                seenIds.add(d.streamId);
                                // Don't show the host their own stream as a "join" card —
                                // they already have it open via the local call in the
                                // go-live-form handler.
                                // FIX (bug: host sees own stream as a joinable card / guests get
                                // an empty hostId): the active_streams doc written by
                                // publishLiveStreamToFirestore() (app-live.js) uses the field name
                                // `hostId`, not `hostUserId` — this listener was reading the wrong
                                // field, so d.hostUserId was ALWAYS undefined here. That broke two
                                // things at once: (1) the "hide the host's own stream" check below
                                // never matched, so the host could see their own live card render
                                // as a joinable stream; and (2) every OTHER viewer's dashboard card
                                // got hostId='' baked into its dataset, so joining a stream left
                                // liveStreamData.hostUserId empty for guests — breaking anything
                                // downstream that needs to know who the real host is (gifting,
                                // muting, notifications, isHost() comparisons). Reading `d.hostId`
                                // (falling back to `d.hostUserId` for any older doc shape) fixes
                                // both without touching the write side.
                                var _liveCardHostId = d.hostId || d.hostUserId || '';
                                if (!isGuest && userState && userState.id === _liveCardHostId) return;
                                createDashboardLiveCard(d.streamId, d.title || 'Live Stream', d.hostName || 'User', d.hostAvatar || '', d.background || '', _liveCardHostId);
                            });
                            // Remove cards for streams that ended or are no longer live
                            const slider = document.getElementById('dashboard-live-slider');
                            if (slider) {
                                slider.querySelectorAll('.live-stream-preview-card[data-stream-id]').forEach(function (card) {
                                    if (!seenIds.has(card.dataset.streamId)) card.remove();
                                });
                                const emptyEl = document.getElementById('live-slider-empty');
                                if (emptyEl) emptyEl.style.display = slider.querySelector('.live-stream-preview-card') ? 'none' : '';
                            }
                        }, function (err) {
                            console.warn('[Live] syncLiveStreamsFromFirestore listener error:', err && err.message);
                        });
                } catch (eSyncLive) { console.warn('[Live] syncLiveStreamsFromFirestore threw:', eSyncLive && eSyncLive.message); }
            }
            window.syncLiveStreamsFromFirestore = syncLiveStreamsFromFirestore;
            document.addEventListener('empyrean-init-done', function () { setTimeout(syncLiveStreamsFromFirestore, 500); });
            window.addEventListener('empyrean:firebase-ready', function () { setTimeout(syncLiveStreamsFromFirestore, 300); });

            // ── AGORA RTC — REAL AUDIO/VIDEO TRANSPORT ────────────────────────────
            // The Firestore sync above only solved DISCOVERY (other users finding out
            // a stream exists). It moves zero video/audio. Before this block, the
            // Agora SDK was loaded in index.html but AgoraRTC.createClient() was
            // NEVER called anywhere in the app — the "camera preview" on go-live was
            // local getUserMedia() shown only in the host's own <video> element, and
            // tapping "Join Live" opened the modal with no actual video source.
            //
            //   • joinAgoraAsHost(channelName, mediaStream) — publishes the host's
            //     already-acquired camera/mic tracks (from startHostCamera below) to
            //     the Agora channel. Wraps the EXISTING MediaStreamTrack via
            //     createCustomAudioTrack/VideoTrack so the browser does NOT prompt
            //     for camera/mic permission a second time.
            //   • joinAgoraAsViewer(channelName) — joins as a subscriber and renders
            //     the host's remote video/audio into #host-main-video.
            //   • leaveAgoraChannel() — unpublishes/leaves and releases tracks;
            //     hooked into the existing live-close-btn cleanup.
            //
            // Tokens are signed server-side only (see POST /api/agora-token in
            // server.js) — the Agora App Certificate never reaches the client, only
            // the short-lived token + the (public) App ID do.
            let _agoraClient = null;
            let _agoraLocalTracks = [];
            let _agoraJoinedChannel = null;

            function _agoraApiBase() {
                // Always same-origin as the page (or the file:// fallback
                // for local testing) — see window._empApiBase() in
                // index.html, the single shared source of truth every
                // API-calling file in this app now uses instead of a
                // hardcoded domain.
                return window._empApiBase();
            }
            function _agoraAppId() {
                return (window._appConfig && window._appConfig.agora && window._appConfig.agora.appId) || '';
            }
            function _fetchAgoraToken(channelName, uid, role) {
                return fetch(_agoraApiBase() + '/api/agora-token', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ channelName: channelName, uid: uid || 0, role: role })
                }).then(function (r) {
                    if (!r.ok) throw new Error('Token request failed: HTTP ' + r.status);
                    return r.json();
                });
            }
            function _agoraUidFor(userId) {
                // Stable small numeric uid derived from the user's id string, so the
                // same person gets the same Agora uid across rejoins/reconnects.
                if (!userId) return Math.floor(Math.random() * 1000000) + 1;
                let h = 0;
                for (let i = 0; i < userId.length; i++) { h = ((h << 5) - h + userId.charCodeAt(i)) | 0; }
                return (Math.abs(h) % 1000000) + 1;
            }

            async function joinAgoraAsHost(channelName, mediaStream) {
                if (typeof AgoraRTC === 'undefined' || window._agoraAvailable === false) {
                    console.warn('[Agora] SDK unavailable — stream will stay local-preview only.');
                    return;
                }
                if (!_agoraAppId()) {
                    console.warn('[Agora] App ID not loaded yet from /api/config — cannot publish.');
                    return;
                }
                if (_agoraJoinedChannel === channelName) return; // already publishing to this channel
                try {
                    if (_agoraClient) { try { await leaveAgoraChannel(); } catch (eLeave) {} }
                    _agoraClient = AgoraRTC.createClient({ mode: 'live', codec: 'vp8' });
                    await _agoraClient.setClientRole('host');

                    const uid = _agoraUidFor(userState.id);
                    const tokenRes = await _fetchAgoraToken(channelName, uid, 'host');
                    await _agoraClient.join(tokenRes.appId, channelName, tokenRes.token, tokenRes.uid || uid);

                    const videoTrackNative = mediaStream.getVideoTracks()[0];
                    const audioTrackNative = mediaStream.getAudioTracks()[0];
                    _agoraLocalTracks = [];
                    if (audioTrackNative) _agoraLocalTracks.push(AgoraRTC.createCustomAudioTrack({ mediaStreamTrack: audioTrackNative }));
                    if (videoTrackNative) _agoraLocalTracks.push(AgoraRTC.createCustomVideoTrack({ mediaStreamTrack: videoTrackNative }));

                    if (_agoraLocalTracks.length) await _agoraClient.publish(_agoraLocalTracks);
                    _agoraJoinedChannel = channelName;
                    console.log('[Agora] ✅ Host publishing to channel', channelName);
                } catch (err) {
                    console.warn('[Agora] Host join/publish failed:', err && err.message);
                }
            }

            async function joinAgoraAsViewer(channelName) {
                if (typeof AgoraRTC === 'undefined' || window._agoraAvailable === false) {
                    console.warn('[Agora] SDK unavailable — cannot view live stream.');
                    return;
                }
                if (!_agoraAppId()) {
                    console.warn('[Agora] App ID not loaded yet from /api/config — cannot join as viewer.');
                    return;
                }
                if (_agoraJoinedChannel === channelName) return; // already viewing this channel
                try {
                    if (_agoraClient) { try { await leaveAgoraChannel(); } catch (eLeave) {} }
                    _agoraClient = AgoraRTC.createClient({ mode: 'live', codec: 'vp8' });
                    await _agoraClient.setClientRole('audience');

                    _agoraClient.on('user-published', async function (user, mediaType) {
                        await _agoraClient.subscribe(user, mediaType);
                        const connectMsgEl = document.getElementById('agora-connecting-msg');
                        if (connectMsgEl) connectMsgEl.remove();
                        const hostVideo = document.getElementById('host-main-video');
                        const fallbackAvatar = document.getElementById('host-video-fallback-avatar');
                        if (mediaType === 'video' && user.videoTrack) {
                            if (hostVideo) { hostVideo.style.display = ''; user.videoTrack.play(hostVideo); }
                            if (fallbackAvatar) fallbackAvatar.style.display = 'none';
                        }
                        if (mediaType === 'audio' && user.audioTrack) {
                            user.audioTrack.play();
                        }
                    });
                    _agoraClient.on('user-unpublished', function (user, mediaType) {
                        if (mediaType === 'video') {
                            const fallbackAvatar = document.getElementById('host-video-fallback-avatar');
                            if (fallbackAvatar) fallbackAvatar.style.display = 'block';
                        }
                    });

                    const uid = _agoraUidFor(userState && userState.id);
                    const tokenRes = await _fetchAgoraToken(channelName, uid, 'viewer');
                    await _agoraClient.join(tokenRes.appId, channelName, tokenRes.token, tokenRes.uid || uid);
                    _agoraJoinedChannel = channelName;
                    console.log('[Agora] ✅ Viewer joined channel', channelName);
                } catch (err) {
                    console.warn('[Agora] Viewer join failed:', err && err.message);
                    const connectMsgEl2 = document.getElementById('agora-connecting-msg');
                    if (connectMsgEl2) connectMsgEl2.innerHTML = '<span style="font-size:0.9rem;opacity:0.85;">Could not connect to live stream.</span>';
                }
            }

            async function leaveAgoraChannel() {
                try {
                    if (_agoraClient) {
                        try { await _agoraClient.unpublish(_agoraLocalTracks); } catch (eUnpub) {}
                        _agoraLocalTracks.forEach(function (t) { try { t.close(); } catch (eClose) {} });
                        _agoraLocalTracks = [];
                        try { await _agoraClient.leave(); } catch (eLeave2) {}
                        _agoraClient = null;
                    }
                } finally {
                    _agoraJoinedChannel = null;
                }
            }

            window.joinAgoraAsHost   = joinAgoraAsHost;
            window.joinAgoraAsViewer = joinAgoraAsViewer;
            window.leaveAgoraChannel = leaveAgoraChannel;

            function addRecordedLiveStream(title, hostName, recordedBlobUrl) {
                const wrapper = document.getElementById('livestream-wrapper');
                if (!wrapper) return;

                // Remove existing card for same title to avoid duplicates when cloud URL arrives
                const existing = Array.from(wrapper.querySelectorAll('.livestream-card')).find(c => c.dataset.title === title);
                if (existing) existing.remove();

                const newCard = document.createElement('div');
                newCard.className = 'livestream-card';
                newCard.dataset.title = title;
                newCard.style.cssText = 'border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(10,14,39,0.1);background:white;margin-bottom:16px;';

                if (recordedBlobUrl) {
                    // Determine type from URL
                    const isCloudMp4 = recordedBlobUrl.includes('cloudinary') || recordedBlobUrl.endsWith('.mp4');
                    const videoEl = document.createElement('video');
                    videoEl.controls = true;
                    videoEl.preload = 'metadata';
                    videoEl.style.cssText = 'width:100%;display:block;max-height:320px;background:#000;';
                    videoEl.src = recordedBlobUrl;
                    if (isCloudMp4) videoEl.type = 'video/mp4';

                    // Download button
                    const dlBtn = document.createElement('a');
                    dlBtn.href = recordedBlobUrl;
                    dlBtn.download = (title || 'recording') + '.webm';
                    dlBtn.style.cssText = 'display:inline-flex;align-items:center;gap:6px;background:var(--secondary);color:white;padding:7px 14px;border-radius:8px;font-size:0.78rem;font-weight:700;text-decoration:none;margin-top:8px;';
                    dlBtn.innerHTML = '<i class="fas fa-download"></i> Download Recording';

                    const info = document.createElement('div');
                    info.style.cssText = 'padding:12px 14px;';
                    info.innerHTML = '<strong style="font-size:0.9rem;color:var(--primary);display:block;margin-bottom:4px;">' + (title||'Recorded Stream') + '</strong>' +
                        '<span style="font-size:0.78rem;color:var(--text-muted);">By: ' + hostName + '</span>' +
                        '<span style="display:block;font-size:0.72rem;color:var(--text-muted);margin-top:2px;">' + new Date().toLocaleString() + '</span>';
                    info.appendChild(dlBtn);

                    newCard.appendChild(videoEl);
                    newCard.appendChild(info);
                } else {
                    newCard.innerHTML = '<div style="height:160px;background:var(--g-navy);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;"><i class="fas fa-video" style="color:rgba(255,255,255,0.35);font-size:2rem;"></i><span style="color:rgba(255,255,255,0.5);font-size:0.8rem;">Recording unavailable</span></div><div style="padding:12px 14px;"><strong style="color:var(--primary);">' + (title||'Stream') + '</strong><br><span style="font-size:0.78rem;color:var(--text-muted);">By: ' + hostName + '</span></div>';
                }

                wrapper.prepend(newCard);

                // Make sure the recorded livestreams section is visible
                const recSection = document.querySelector('.recorded-livestreams, #recorded-livestreams-section');
                if (recSection) recSection.style.display = 'block';
                // Navigate to livestream section to show it
                const liveSection = document.getElementById('go-live');
                if (liveSection) {
                    const wrapperSection = liveSection.querySelector('#livestream-wrapper');
                    if (wrapperSection) wrapperSection.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                }
            }

            function updateLiveUI() {
                const isCurrentUserHost = !isGuest && userState.id === liveStreamData.hostUserId;
                const liveContainer = liveStreamScreen;
                const hostMainVideo = document.getElementById('host-main-video');
                const hostVideoFallbackAvatar = document.getElementById('host-video-fallback-avatar');
                const hostControlPanel = document.getElementById('host-control-panel');
                const hostControlToggleBtn = document.getElementById('host-control-toggle-btn');
                
                const currentBg = liveStreamData.customBackgroundFile ? URL.createObjectURL(liveStreamData.customBackgroundFile) : liveStreamData.background;
                const isImageBg = currentBg && (currentBg.startsWith('http') || currentBg.startsWith('blob:'));
                liveContainer.style[isImageBg ? 'backgroundImage' : 'background'] = isImageBg ? `url('${currentBg}')` : currentBg;
                liveContainer.style.backgroundSize = 'cover';
                liveContainer.style.backgroundPosition = 'center';

                if (hostControlPanel && hostControlToggleBtn) {
                    // TEMP DIAGNOSTIC (remove once host-control-panel visibility bug is confirmed/fixed):
                    // logs the exact inputs updateLiveUI() used to decide panel visibility, plus the
                    // panel's actual rendered box on screen, every time this function runs.
                    console.log('[HCP-DIAG]', {
                        isCurrentUserHost,
                        isGuest,
                        myUserId: userState && userState.id,
                        hostUserId: liveStreamData && liveStreamData.hostUserId,
                        panelDisplayBefore: hostControlPanel.style.display,
                        panelComputedDisplay: window.getComputedStyle(hostControlPanel).display,
                        panelRect: hostControlPanel.getBoundingClientRect(),
                        toggleBtnRect: hostControlToggleBtn.getBoundingClientRect()
                    });
                    // FIX (bug: "guest camera/mic panel not wired" — root
                    // cause was this exact block hiding the whole panel):
                    // an accepted guest broadcaster's mic/video toggle
                    // buttons live inside this same #host-control-panel
                    // (see app-live-tiktok-patch.js), which already shows
                    // the panel for that case and marks it with the
                    // 'tk-guest-broadcast-mode' class. This function used
                    // to unconditionally hide the panel for anyone who
                    // isn't the host, with no awareness of that case — and
                    // since this function is called from ~25 other places
                    // (any of which could fire right after the guest taps
                    // mic/video), it kept re-hiding the panel out from
                    // under the guest a moment after it appeared.
                    var isGuestBroadcasterPanel = hostControlPanel.classList.contains('tk-guest-broadcast-mode');
                    if (isCurrentUserHost) {
                        hostControlPanel.style.display = 'flex'; // Ensure panel is displayed for host
                        // hostControlPanel.classList.add('expanded'); // Start expanded - Let user toggle
                        hostControlToggleBtn.querySelector('i').className = hostControlPanel.classList.contains('expanded') ? 'fas fa-chevron-left' : 'fas fa-chevron-right'; // Update toggle icon
                    } else if (isGuestBroadcasterPanel) {
                        hostControlPanel.style.display = 'flex'; // leave the guest broadcaster's mic/video panel alone
                    } else {
                        hostControlPanel.style.display = 'none';
                        hostControlPanel.classList.remove('expanded');
                    }
                }
                
                const liveRequestJoinBtn = document.getElementById('live-request-join-btn');
                if (liveRequestJoinBtn) {
                     liveRequestJoinBtn.style.display = (!isCurrentUserHost && !isGuest && liveStreamData.guests.length < 9) ? 'flex' : 'none';
                     // FIX 2026-07-23 (bug: "send request button not working"):
                     // this block used to ALSO independently toggle
                     // liveRequestJoinBtn.disabled and overwrite its innerHTML
                     // (a "pv37" pending/idle state machine, guarded by a
                     // dataset.pv37UiState flag), running every time
                     // updateLiveUI() fires -- which is essentially every
                     // stream state change. app-live-tiktok-patch.js's own
                     // sendJoinRequest()/setReqTileState() already own this
                     // button's disabled state and icon, driven by the real,
                     // Firestore-confirmed dataset.requested flag. Two
                     // independent systems flipping .disabled on the same
                     // native <button> is a real risk of it getting left
                     // disabled -- and a disabled <button> doesn't dispatch
                     // click events at all, so it would look exactly like
                     // "tapping does nothing", with no console output.
                     // Now this block ONLY shows/hides the button; the
                     // dataset.requested-driven flow in
                     // app-live-tiktok-patch.js is the single owner of its
                     // enabled/disabled state and icon.
                }

                const liveRecordBtn = document.getElementById('live-record-btn');
                if (liveRecordBtn) liveRecordBtn.classList.toggle('recording', liveStreamData.isRecording);
                const liveMicToggle = document.getElementById('live-mic-toggle');
                const liveVideoToggle = document.getElementById('live-video-toggle');
                // FIX (bug #3, part 2): only the host's own mute state lives in
                // liveStreamData.isMicMuted/isVideoMuted — don't let this
                // overwrite an accepted guest broadcaster's icon, which
                // app-live-tiktok-patch.js already owns and keeps correct
                // via its own _guestMicMuted/_guestCamOff state.
                if (!hostControlPanel || !hostControlPanel.classList.contains('tk-guest-broadcast-mode')) {
                    if (liveMicToggle) liveMicToggle.innerHTML = `<i class="fas fa-microphone${liveStreamData.isMicMuted ? '-slash' : ''}"></i>`;
                    if (liveVideoToggle) liveVideoToggle.innerHTML = `<i class="fas fa-video${liveStreamData.isVideoMuted ? '-slash' : ''}"></i>`;
                }
                const liveShareScreenBtn = document.getElementById('live-share-screen-btn');
                if (liveShareScreenBtn) {
                    liveShareScreenBtn.innerHTML = `<i class="fas fa-desktop${liveStreamData.isScreenSharing ? '-slash' : ''}"></i>`;
                    liveShareScreenBtn.classList.toggle('recording', liveStreamData.isScreenSharing);
                }
                
                if (hostMainVideo && hostVideoFallbackAvatar) {
                    // FIX (mock-data removal): this block used to hard-assign
                    // hostMainVideo.src = "…w3schools…mov_bbb.mp4" (a placeholder
                    // stock video) EVERY time updateLiveUI() ran — i.e. on every
                    // mic toggle, guest join, chat message, gift, etc. (25+ call
                    // sites). app-live.js's real Agora pipeline attaches the
                    // genuine camera/remote stream to this same #host-main-video
                    // element via `.srcObject`. A <video> can't coherently hold
                    // both `.src` and `.srcObject` at once, so every call here was
                    // silently clobbering the real Agora feed with the fake clip —
                    // this is why the stream looked broken/black. This function now
                    // ONLY toggles visibility/mute state; it never touches .src or
                    // .srcObject — that is exclusively Agora's job now.
                    if (isCurrentUserHost) {
                        hostMainVideo.style.display = liveStreamData.isVideoMuted ? 'none' : 'block';
                        if (!liveStreamData.isVideoMuted) {
                            hostMainVideo.muted = liveStreamData.isMicMuted;
                        }
                        hostVideoFallbackAvatar.style.display = liveStreamData.isVideoMuted ? 'block' : 'none';
                        hostVideoFallbackAvatar.src = document.getElementById('live-host-avatar').src;
                    } else { // For guests viewing
                        hostMainVideo.style.display = liveStreamData.isVideoMuted ? 'none' : 'block';
                        if (!liveStreamData.isVideoMuted) {
                            hostMainVideo.muted = false;
                        }
                        hostVideoFallbackAvatar.style.display = liveStreamData.isVideoMuted ? 'block' : 'none';
                        hostVideoFallbackAvatar.src = document.getElementById('live-host-avatar').src;
                    }
                }

                // REMOVED (mock-data cleanup): this block used to render
                // liveStreamData.guests (a local array only ever populated by the
                // now-removed mock .accept-guest-btn handler) into
                // #multi-guest-slots, AND — critically — force
                // #multi-guest-container's display to 'none' whenever that local
                // array was empty. app-live-tiktok-patch.js renders the real,
                // Firestore-driven guest boxes (see renderGuestBoxStack()) directly
                // into that same #multi-guest-container element. With
                // liveStreamData.guests never populated anymore, this block would
                // run on every one of updateLiveUI()'s 25+ call sites and
                // immediately hide the real guest video the tiktok patch had just
                // shown. Guest-slot rendering and visibility are now owned
                // entirely by app-live-tiktok-patch.js's Firestore listener.


                const goalDisplay = document.getElementById('live-goals-display');
                if (goalDisplay) {
                    if (liveStreamData.liveGoal) {
                        goalDisplay.style.display = 'flex';
                        const currentAmount = liveStreamData.liveGoal.currentAmount || 0;
                        const targetAmount = liveStreamData.liveGoal.targetAmount;
                        document.getElementById('live-goal-text').textContent = `${liveStreamData.liveGoal.description} (${Math.floor(currentAmount)}/${targetAmount} EMPY)`;
                        const progress = (currentAmount / targetAmount) * 100;
                        document.getElementById('live-goal-progress').style.width = `${Math.min(progress, 100)}%`;
                    } else {
                        goalDisplay.style.display = 'none';
                    }
                }

                const fanClubDisplay = document.getElementById('live-fan-club-display');
                if (fanClubDisplay) fanClubDisplay.style.display = liveStreamData.fanClubActive ? 'flex' : 'none';

                const gamesDisplay = document.getElementById('live-games-display');
                if (gamesDisplay) {
                    if (liveStreamData.activeGame) {
                        gamesDisplay.style.display = 'flex';
                        document.getElementById('live-game-name').textContent = liveStreamData.activeGame.name || liveStreamData.activeGame.type.charAt(0).toUpperCase() + liveStreamData.activeGame.type.slice(1);
                    } else {
                        gamesDisplay.style.display = 'none';
                    }
                }

                // Pinned message visibility fix: Adjusted Z-index and ensures it's above host avatar.
                const pinnedMessageDisplay = document.getElementById('live-pinned-message-display');
                if (pinnedMessageDisplay) {
                    if (liveStreamData.pinnedMessage) {
                        pinnedMessageDisplay.style.display = 'flex';
                        const pinnedContentSpan = pinnedMessageDisplay.querySelector('.pinned-content');
                        if (pinnedContentSpan) {
                            pinnedContentSpan.textContent = liveStreamData.pinnedMessage.content;
                        }
                    } else {
                        pinnedMessageDisplay.style.display = 'none';
                    }
                }

                const closeButton = goLiveModal.querySelector('#live-close-btn');
                if (closeButton) {
                    closeButton.innerHTML = isCurrentUserHost ? 'End' : '&times;';
                    closeButton.title = isCurrentUserHost ? 'End Stream' : 'Leave Stream';
                }

                // FIX (mock-data removal, round 2): this used to force
                // #live-viewer-count/#modal-viewer-count to the fixed formula
                // "1 + liveStreamData.guests.length" on EVERY updateLiveUI() call
                // (25+ call sites — any mic toggle, chat message, etc.). Removed —
                // app-live.js is the only writer of these two elements. UPDATE:
                // it no longer drives them from local Agora user-published/
                // user-left deltas either (those only fired for guests who
                // actively publish, never plain audience) — it now runs a
                // shared Firestore presence listener (_startViewerCountListener,
                // backed by active_streams/{id}/viewers/{uid} docs) so the number
                // is the same real, synced count on every device watching.
            }

            function renderGuestJoinRequests() {
                const requestList = document.getElementById('live-join-requests-list');
                const requestCount = document.getElementById('live-join-request-count');
                if (!requestList || !requestCount) return;

                requestList.innerHTML = '';
                requestCount.textContent = liveStreamData.joinRequests.length;

                if (liveStreamData.joinRequests.length === 0) {
                    requestList.innerHTML = '<p style="text-align:center; color:#ccc; padding:20px;">No pending requests.</p>';
                    return;
                }

                liveStreamData.joinRequests.forEach(req => {
                    const reqEl = document.createElement('div');
                    reqEl.className = 'viewer-item';
                    reqEl.innerHTML = `
                        <img src="${req.avatar}" alt="${req.username}">
                        <div class="viewer-item-info">
                            <strong>${req.fullName}</strong>
                            <span>@${req.username}</span>
                        </div>
                        <div class="viewer-actions">
                            <button class="btn btn-small btn-success accept-guest-btn" data-user-id="${req.userId}">Accept</button>
                            <button class="btn btn-small btn-danger reject-guest-btn" data-user-id="${req.userId}">Reject</button>
                        </div>
                    `;
                    requestList.appendChild(reqEl);
                });
            }

            function renderHostSentMessagesForPinning() {
                const messagesList = document.getElementById('live-host-sent-messages');
                if (!messagesList) return;

                messagesList.innerHTML = '';
                if (liveStreamData.sentMessages.length === 0) {
                    messagesList.innerHTML = '<p style="text-align:center; color:#ccc; padding:20px;">No messages sent yet during this stream.</p>';
                    return;
                }

                liveStreamData.sentMessages.forEach(msg => {
                    const msgEl = document.createElement('div');
                    msgEl.className = `pin-message-choice ${liveStreamData.pinnedMessage && liveStreamData.pinnedMessage.id === msg.id ? 'selected' : ''}`;
                    msgEl.dataset.messageId = msg.id;
                    msgEl.innerHTML = `
                        <strong>@${msg.username}</strong>
                        <p>${formatWhatsAppText(msg.content)}</p>
                    `;
                    messagesList.prepend(msgEl);
                });
            }


