            // REMOVED (2026-08-06): a dead, never-called local
            // addMarketItemToDashboardSlider() used to live here — fully
            // superseded by window.addMarketItemToDashboardSlider (aliased
            // in app-marketplace.js to addMarketItemToDashboardStrip),
            // which is the only version anything in this codebase actually
            // calls (see the `window.addMarketItemToDashboardSlider(...)`
            // call below). Left in place before, it was orphaned old-card
            // code with no call site — removed so it can't be mistaken for
            // the active implementation or accidentally invoked bare.
            



            // FIX (root cause of "share icon works once then freezes"):
            // shareContent() used to fire straight into navigator.share()
            // with no guard, so a second tap while the first native share
            // sheet (or clipboard write) was still resolving hit the
            // browser's own "Only one share can be in progress at a time"
            // InvalidStateError — that could surface as an uncaught error on
            // the very next tap, and even when it didn't, the second tap
            // produced no visible result, indistinguishable from the button
            // being dead. _shareContentBusy makes an overlapping call a
            // safe, user-visible no-op instead, and is always cleared in a
            // finally so a slow or failed share can never leave the button
            // stuck "busy" for good.
            let _shareContentBusy = false;
            async function shareContent(shareData) {
                if (_shareContentBusy) {
                    showNotification('Share already in progress — one moment…', 'info');
                    return;
                }
                _shareContentBusy = true;
                try {
                    let copied = false;
                    if (navigator.clipboard) {
                        try {
                            await navigator.clipboard.writeText(shareData.url);
                            showNotification('Link copied to clipboard!');
                            copied = true;
                        } catch (err) { console.error('Failed to copy link: ', err); }
                    }

                    if (navigator.share) {
                        try { await navigator.share(shareData); }
                        catch (err) { if (err.name !== 'AbortError') { console.error('Web Share API Error:', err); } }
                    } else if (!copied) {
                        showNotification('Sharing not supported on this browser.', 'error');
                    }
                    rewardUserForAction('SHARE_POST');
                    if (typeof updateLiveInteractionCount === 'function') updateLiveInteractionCount('like');
                } finally {
                    _shareContentBusy = false;
                }
            }
            
            function setupReelViewerObserver() {
                const reelViewerContainer = document.getElementById('reel-viewer-container');
                if (!reelViewerContainer) return; 

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        const video = entry.target.querySelector('video');
                        if (video) { 
                            if (entry.isIntersecting) {
                                video.play().catch(e => console.log("Autoplay was prevented for reel video.", e));
                            } else {
                                video.pause();
                            }
                        }
                    });
                }, { threshold: 0.5 });

                reelViewerContainer.querySelectorAll('.reel-viewer-item').forEach(item => {
                    observer.observe(item);
                });
            }

            
