                            const budgetInUsd     = budget / USD_TO_NGN_RATE;
                            const budgetInEmpy   = budgetInUsd / EMPY_RATE_USD;
                            const postId         = promotePostIdInput.value;
                            const durationDays   = parseInt(promoDurationSelect && promoDurationSelect.value, 10) || 3;

