                                            // fails after that, it's just no longer mistaken for one.
                                            try {
                                                await window.fbDb.collection('marketplace_listings').doc(itemId).set(listingData);
                                            } catch (firstErr) {
                                                var _isPermErr = firstErr && (firstErr.code === 'permission-denied' || /insufficient|permission/i.test(firstErr.message || ''));
                                                if (_isPermErr && window.fbAuth && window.fbAuth.currentUser && typeof window.fbAuth.currentUser.getIdToken === 'function') {
                                                    console.warn('[Marketplace] listing save denied — refreshing token and retrying once:', firstErr.message);
                                                    try { await window.fbAuth.currentUser.getIdToken(true); } catch (tokenErr) {}
                                                    await window.fbDb.collection('marketplace_listings').doc(itemId).set(listingData);
                                                } else {
                                                    throw firstErr;
                                                }
                                            }
                                            // FIX (bug: "no notification for new posts / doesn't cross-
                                            // populate across devices"): marketplace listings were another
                                            // silent content-creation path -- _ICON_MAP already had a
