            // renderer actually wired to the live app — app-ngo.js's
            // renderCommunityTasks() is, and it runs after this one on
            // every real render path, silently overwriting whatever this
            // IIFE just built. That's why the 2026-07-24 premium redesign
            // applied here never appeared live; the redesign that actually
            // ships now lives in app-ngo.js's renderCommunityTasks()
            // instead (same markup/classes, same inline-SVG icons).
            // Left inert rather than deleted, per this codebase's
            // no-deletion convention (see app-patch-v4.js's own
            // fixBusinessPage_DISABLED for the same pattern) — do not
            // re-enable without first disabling app-ngo.js's version, or
            // the two will race and the visible result will depend on
            // whichever call site fires last.
            (function() {
                return; /* intentionally inert — see disabled note above */

                const taskList = document.getElementById('community-tasks-list');
                if (!taskList || typeof mockCommunityTasks === 'undefined') return;

                // FIX (2026-07-24 — premium redesign / broken icons): brand
                // icons used to come from the Font Awesome brand webfont
                // (fab fa-x-twitter, fab fa-instagram, ...). On a slow
                // connection that font can arrive late or not at all,
                // rendering an empty "tofu" box — the same failure mode
                // already fixed on the SOS/Crisis forms. Inline SVG has no
                // external request, so it always renders. Icons are simple,
                // generic line-glyphs representative of each platform
                // rather than reproductions of the official logo artwork.
                var _commTaskIcons = {
                    'x-twitter': '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M18.9 3H22l-7.6 8.7L23 21h-6.6l-5.2-6.5L5.2 21H2l8.1-9.3L1.6 3h6.8l4.7 5.9L18.9 3Zm-1.2 16h1.8L7.4 4.9H5.5L17.7 19Z"/></svg>',
                    'instagram': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4.2"/><circle cx="17.3" cy="6.7" r="1.1" fill="currentColor" stroke="none"/></svg>',
                    'youtube': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="2" y="5" width="20" height="14" rx="4"/><path d="M10 9.3v5.4l4.8-2.7-4.8-2.7Z" fill="currentColor" stroke="none"/></svg>',
                    'linkedin': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="3"/><line x1="7.5" y1="10.2" x2="7.5" y2="17"/><circle cx="7.5" cy="6.8" r="0.9" fill="currentColor" stroke="none"/><path d="M11.3 17v-4.3c0-1.6 1-2.4 2.3-2.4 1.3 0 2.2.8 2.2 2.4V17"/><line x1="11.3" y1="10.2" x2="11.3" y2="17"/></svg>',
                    'telegram': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>',
                    'whatsapp': '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5Z"/></svg>'
                };
                var _commTaskArrowIcon  = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>';
                var _commTaskCheckIcon  = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>';

                taskList.innerHTML = '';
                mockCommunityTasks.forEach(task => {
                    const isCompleted = userState.completedTasks instanceof Set
                        ? userState.completedTasks.has(task.id)
                        : false;
                    const li = document.createElement('li');
                    li.className = 'comm-task-item';
                    li.dataset.taskId = task.id;
                    li.innerHTML = `
                        <div class="comm-task-info">
                            <span class="comm-task-icon">${_commTaskIcons[task.icon] || ''}</span>
                            <div class="comm-task-text">
                                <strong>${task.text}</strong>
                                <span class="comm-task-reward-amt">+${task.reward} EMPY</span>
                            </div>
                        </div>
                        ${isCompleted
                            ? `<span class="comm-task-done">${_commTaskCheckIcon} Done</span>`
                            : `<a href="${task.url}" target="_blank" rel="noopener" class="comm-task-cta task-complete-btn" data-task-id="${task.id}" data-reward="${task.reward}">
                                Go &amp; Earn ${_commTaskArrowIcon}
                               </a>`
                        }
                    `;
                    taskList.appendChild(li);
                });

                // Task completion handler
                document.addEventListener('click', function(e) {
                    const taskBtn = e.target.closest('.task-complete-btn');
                    if (!taskBtn) return;
                    const taskId = taskBtn.dataset.taskId;
                    const reward = parseInt(taskBtn.dataset.reward) || 0;
                    // Mark completed after 3 seconds (simulate link visit)
                    setTimeout(() => {
                        if (userState.completedTasks instanceof Set && !userState.completedTasks.has(taskId)) {
                            userState.completedTasks.add(taskId);
                            userState.empyBalance = (userState.empyBalance || 0) + reward;
                            showNotification(`🎉 +${reward} EMPY earned for completing task!`, 'success');
                            // Re-render tasks
                            const btn = document.querySelector(`.task-complete-btn[data-task-id="${taskId}"]`);
                            if (btn) btn.outerHTML = `<span class="comm-task-done">${_commTaskCheckIcon} Done</span>`;
                            updateWalletUI && updateWalletUI();
                        }
                    }, 3000);
                });
            })();

