                            // FEATURE (2026-09-01 -- "adjust or move the quote or meme
                            // card"): offsetXFrac/offsetYFrac (0 = the original fixed
                            // spot) come from dragging the preview canvas -- see the
                            // pointer wiring in _ensureOverlay below -- and are clamped
                            // so the card can be nudged around but never dragged off the
                            // canvas edge, whatever quote length pushed cardH to.
                            var offsetXFrac = opts.offsetXFrac || 0, offsetYFrac = opts.offsetYFrac || 0;
                            var minX = size * 0.02, maxX = size - cardW - size * 0.02;
                            var minY = size * 0.02, maxY = size - cardH - size * 0.02;
