                'display:none', 'position:fixed', 'inset:0',
                'background:rgba(0,0,0,0.93)', 'z-index:99999',
                'align-items:center', 'justify-content:center',
                'cursor:zoom-out', '-webkit-tap-highlight-color:transparent'
